import React from 'react';
import { ChevronRight } from 'lucide-react';

const LoginScreen = () => {
  return (
    <div className="min-h-screen w-full bg-gradient-to-b from-[#1a5fb4] to-[#0d3d82] flex flex-col items-center justify-center p-6 font-sans">

      {/* 1. 상단 로고 영역 (파일 대신 코드로 직접 그림) */}
      <div className="w-full max-w-[280px] aspect-square bg-white/10 backdrop-blur-md rounded-3xl border border-white/20 flex items-center justify-center shadow-2xl mb-10 relative overflow-hidden">

        {/* 로고 컨테이너 */}
        <div className="relative z-10 flex flex-col items-center justify-center p-8">

            {/* SVG 로고: 파일 없이 코드로 구현된 DC 로고 */}
            <svg width="120" height="120" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
              {/* 왼쪽 D 기둥 (진한 남색) */}
              <path d="M25 10H45V90H25V10Z" fill="#1e2f55"/>
              {/* 오른쪽 C 형태 (진한 남색) */}
              <path d="M55 10H75V55L55 55V10Z" fill="#1e2f55"/>
              <path d="M55 65H75V90H55V65Z" fill="#1e2f55"/>
              <path d="M20 90H80C80 90 85 90 85 85" stroke="#1e2f55" strokeWidth="0"/> 

              {/* 하단 받침 (곡선 느낌 추가) */}
              <path d="M15 92C15 92 30 88 50 88C70 88 85 92 85 92" stroke="#1e2f55" strokeWidth="4" strokeLinecap="round"/>

              {/* 체크 마크 (황금색/오렌지) */}
              <path d="M60 45 L70 55 L85 30" stroke="#dfa92c" strokeWidth="8" strokeLinecap="round" strokeLinejoin="round"/>
            </svg>

        </div>
      </div>

      {/* 2. 브랜드 텍스트 */}
      <div className="text-center mb-8">
        <h1 className="text-4xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-100 to-white tracking-tighter mb-2" style={{fontFamily: 'Arial, sans-serif'}}>
          DOUBLE CHECK
        </h1>
        <div className="bg-blue-500/30 backdrop-blur-sm px-4 py-1.5 rounded-full border border-blue-400/30 inline-block">
           <span className="text-blue-100 text-xs font-semibold tracking-widest uppercase">
            Verified Perfection
          </span>
        </div>
      </div>

      {/* 3. 로그인 폼 영역 */}
      <div className="w-full max-w-sm bg-white/10 backdrop-blur-xl rounded-3xl border border-white/20 p-8 shadow-2xl">

        <div className="mb-8">
          <label className="block text-blue-200 text-xs font-bold uppercase tracking-widest mb-3 ml-1">
            Access Code
          </label>
          <input 
            type="text" 
            placeholder="인증 코드 입력" 
            className="w-full bg-white/5 text-white placeholder-blue-200/50 rounded-xl py-4 px-4 text-center text-xl font-medium focus:outline-none focus:bg-white/10 focus:ring-2 focus:ring-blue-400/50 border border-white/10 transition-all"
          />
        </div>

        <button className="w-full bg-gradient-to-r from-blue-500 to-blue-600 hover:from-blue-400 hover:to-blue-500 text-white font-bold py-4 rounded-xl shadow-lg shadow-blue-900/50 transition-all duration-300 transform hover:-translate-y-1 flex items-center justify-center gap-2 group">
          <span>로그인</span>
          <ChevronRight className="w-5 h-5 group-hover:translate-x-1 transition-transform" />
        </button>

      </div>

      {/* 4. 하단 카피라이트 */}
      <div className="mt-16 text-blue-300/40 text-[10px] tracking-[0.3em] font-medium uppercase">
        Create by Gemini Studio
      </div>

    </div>
  );
};

export default LoginScreen;

