export interface InspectionInfo {
  apartmentName: string;
  unit: string; // Dong/Ho
  typeSize: string; // Pyung/Type
  inspectorName: string;
  phoneNumber: string;
  date: string;
}

export interface DefectItem {
  id: string;
  location: string; // Zone/Room name (e.g., Living Room, Kitchen)
  farPhotos: string[]; // Array of Blob URLs
  nearPhotos: string[]; // Array of Blob URLs
  description: string;
  timestamp: number;
}

export interface CompletedInspection {
  id: string;
  info: InspectionInfo;
  defects: DefectItem[];
  locations: string[];
  savedAt: number;
  defectCount?: number; // Added for lightweight indexing
}

export interface Snapshot {
  id: string;
  timestamp: number;
  info: InspectionInfo;
  defects: DefectItem[];
  locations: string[];
}

export interface AppState {
  step: 'info' | 'capture' | 'preview' | 'archive'; // Added 'archive' step
  info: InspectionInfo;
  defects: DefectItem[];
  locations: string[]; // List of available categories
}

import { get, set, del, clear } from 'idb-keyval';
import { DefectItem, InspectionInfo, AppState, CompletedInspection, Snapshot } from '../types';

const KEYS = {
  STEP: 'app_step',
  INFO: 'app_info',
  DEFECTS: 'app_defects',
  LOCATIONS: 'app_locations',
  DRAFT: 'app_draft',
  ARCHIVE: 'app_archive',
  SNAPSHOTS: 'app_snapshots', // New: Temp Archive
  LOGO: 'app_logo', // New: Logo
  // Auth keys
  AUTH_TIMESTAMP: 'app_auth_last_active' // LocalStorage (Time check)
};

const SESSION_KEY = 'app_session_active'; // SessionStorage (App kill check)
const ONE_HOUR = 60 * 60 * 1000; // 1 Hour in ms

// --- Auth Helpers ---

// Login: Set both session flag (cleared on app close) and timestamp (for timeout)
export const saveAuth = () => {
  sessionStorage.setItem(SESSION_KEY, 'true');
  localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
};

// Check Auth: Must have Session AND (Current Time - Last Active < 1 Hour)
export const checkAuth = (): boolean => {
  // 1. Check if App was killed/closed (SessionStorage is cleared on browser/tab close)
  const isSessionActive = sessionStorage.getItem(SESSION_KEY);
  if (!isSessionActive) {
    return false;
  }

  // 2. Check 1 Hour Timeout
  const lastActiveStr = localStorage.getItem(KEYS.AUTH_TIMESTAMP);
  if (!lastActiveStr) {
    return false; 
  }

  const lastActive = parseInt(lastActiveStr, 10);
  const now = Date.now();

  if (now - lastActive > ONE_HOUR) {
    // Timeout expired
    clearAuth();
    return false;
  }

  // 3. If valid, refresh the timestamp
  updateAuthTimestamp();
  return true;
};

// Refresh the 1-hour timer (called on user interaction)
export const updateAuthTimestamp = () => {
  if (sessionStorage.getItem(SESSION_KEY)) {
    localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
  }
};

export const clearAuth = () => {
  sessionStorage.removeItem(SESSION_KEY);
  localStorage.removeItem(KEYS.AUTH_TIMESTAMP);
};

// --- Basic Data Access ---
export const saveStep = (step: AppState['step']) => set(KEYS.STEP, step);
export const saveInfo = (info: InspectionInfo) => set(KEYS.INFO, info);
export const saveLocations = (locations: string[]) => set(KEYS.LOCATIONS, locations);

export const loadStep = () => get<AppState['step']>(KEYS.STEP);
export const loadInfo = () => get<InspectionInfo>(KEYS.INFO);
export const loadLocations = () => get<string[]>(KEYS.LOCATIONS);

// --- Handle Defects with Blobs ---
export const saveDefects = async (defects: DefectItem[]) => {
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      })),
      nearPhotos: await Promise.all(d.nearPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      }))
    }))
  );
  await set(KEYS.DEFECTS, defectsWithBlobs);
};

export const loadDefects = async (): Promise<DefectItem[]> => {
  const saved = await get<any[]>(KEYS.DEFECTS);
  if (!saved) return [];
  return saved.map((d) => ({
    ...d,
    farPhotos: d.farPhotos.map((blob: Blob) => URL.createObjectURL(blob)),
    nearPhotos: d.nearPhotos.map((blob: Blob) => URL.createObjectURL(blob))
  }));
};

// --- Draft Handling ---
export const saveDraft = async (data: {
  location: string;
  farPhotos: string[];
  nearPhotos: string[];
  description: string;
  editingId: string | null;
}) => {
  const farBlobs = await Promise.all(data.farPhotos.map(url => fetch(url).then(r => r.blob())));
  const nearBlobs = await Promise.all(data.nearPhotos.map(url => fetch(url).then(r => r.blob())));
  await set(KEYS.DRAFT, { ...data, farPhotos: farBlobs, nearPhotos: nearBlobs });
};

export const loadDraft = async () => {
  const draft = await get<any>(KEYS.DRAFT);
  if (!draft) return null;
  return {
    ...draft,
    farPhotos: draft.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: draft.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
  };
};

export const clearDraft = () => del(KEYS.DRAFT);

export const clearAllData = async () => {
  await del(KEYS.STEP);
  await del(KEYS.INFO);
  await del(KEYS.DEFECTS);
  await del(KEYS.LOCATIONS);
  await del(KEYS.DRAFT);
  // Do NOT clear snapshots or archive
};

// --- LOGO PERSISTENCE ---
export const saveLogo = async (blob: Blob) => {
  await set(KEYS.LOGO, blob);
};

export const loadLogo = async (): Promise<string | null> => {
  const blob = await get<Blob>(KEYS.LOGO);
  return blob ? URL.createObjectURL(blob) : null;
};

// --- SNAPSHOTS (Temp Archive) ---
const MAX_SNAPSHOTS = 6; // Keep last 1 hour (if 10 min interval)

export const saveSnapshot = async (info: InspectionInfo, defects: DefectItem[], locations: string[]) => {
  let snapshots = await get<Snapshot[]>(KEYS.SNAPSHOTS) || [];

  // Convert defect photos to blobs for storage
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(url => fetch(url).then(r => r.blob()))),
      nearPhotos: await Promise.all(d.nearPhotos.map(url => fetch(url).then(r => r.blob())))
    }))
  );

  const newSnapshot: Snapshot = {
    id: Date.now().toString(),
    timestamp: Date.now(),
    info,
    defects: defectsWithBlobs,
    locations
  };

  // Add to beginning, slice to max
  snapshots = [newSnapshot, ...snapshots].slice(0, MAX_SNAPSHOTS);
  await set(KEYS.SNAPSHOTS, snapshots);
};

export const loadSnapshots = async (): Promise<Snapshot[]> => {
  const saved = await get<any[]>(KEYS.SNAPSHOTS);
  if (!saved) return [];

  // Convert blobs back to URLs
  return saved.map(s => ({
    ...s,
    defects: s.defects.map((d: any) => ({
      ...d,
      farPhotos: d.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
      nearPhotos: d.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
    }))
  }));
};

export const deleteSnapshot = async (id: string) => {
  const snapshots = await get<Snapshot[]>(KEYS.SNAPSHOTS) || [];
  const newSnapshots = snapshots.filter(s => s.id !== id);
  await set(KEYS.SNAPSHOTS, newSnapshots);
  return newSnapshots;
};

// --- Archive Handling (Optimized for High Capacity) ---

const getDataKey = (id: string) => `archive_data_${id}`;

export const saveToArchive = async (info: InspectionInfo, defects: DefectItem[], locations: string[]) => {
  const id = Date.now().toString();
  const dataKey = getDataKey(id);

  // 1. Prepare Heavy Data (Defects with Blobs)
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(url => fetch(url).then(r => r.blob()))),
      nearPhotos: await Promise.all(d.nearPhotos.map(url => fetch(url).then(r => r.blob())))
    }))
  );

  // Save heavy data separately
  await set(dataKey, { defects: defectsWithBlobs, locations });

  // 2. Prepare Index Item (Lightweight)
  const indexItem: CompletedInspection = {
    id,
    info,
    defects: [], // Empty to save memory in the list
    locations: [], // Empty to save memory
    savedAt: Date.now(),
    defectCount: defects.length
  };

  let currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  if (!Array.isArray(currentArchive)) currentArchive = [];

  // Add new item to the top
  await set(KEYS.ARCHIVE, [indexItem, ...currentArchive]);
};

export const loadArchive = async (): Promise<CompletedInspection[]> => {
  const archive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  return Array.isArray(archive) ? archive : [];
};

export const loadArchivedItemDetail = async (id: string) => {
  const dataKey = getDataKey(id);
  const data = await get<any>(dataKey);

  if (data) {
     const defects = data.defects.map((d: any) => ({
        ...d,
        farPhotos: d.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
        nearPhotos: d.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
     }));
     return { defects, locations: data.locations };
  }
  return null;
};

export const restoreArchivedItemLegacy = (item: any): { defects: DefectItem[] } => {
  if (!item || !item.defects) return { defects: [] };
  const restoredDefects = item.defects.map((d: any) => ({
    ...d,
    farPhotos: (d.farPhotos || []).map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: (d.nearPhotos || []).map((b: Blob) => URL.createObjectURL(b))
  }));
  return { defects: restoredDefects };
};

export const deleteFromArchive = async (id: string) => {
  const currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  if (!currentArchive) return [];

  const newArchive = currentArchive.filter(item => item.id !== id);
  await set(KEYS.ARCHIVE, newArchive);

  await del(getDataKey(id));

  return newArchive;
};

// --- TEAM COLLABORATION / EXPORT ---

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
        const result = reader.result as string;
        resolve(result);
    };
    reader.onerror = (e) => reject(e);
    reader.readAsDataURL(blob);
  });
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  try {
      const res = await fetch(base64);
      return await res.blob();
  } catch (e) {
      console.error("Error converting base64 to blob", e);
      throw new Error("이미지 변환 실패");
  }
};

const generateUniqueId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substring(2, 5);
};

export const exportActiveDataToDataFile = async (info: InspectionInfo, defects: DefectItem[]): Promise<Blob> => {
  try {
      const serializableDefects = await Promise.all(defects.map(async (d) => {
        const farPhotosB64 = await Promise.all(d.farPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));
        const nearPhotosB64 = await Promise.all(d.nearPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));

        return {
            ...d,
            farPhotos: farPhotosB64,
            nearPhotos: nearPhotosB64
        };
      }));

      const data = {
        version: '2.0',
        type: 'DOUBLECHECK_TEAM_DATA',
        info,
        defects: serializableDefects,
        exportedAt: Date.now()
      };

      const jsonString = JSON.stringify(data);
      return new Blob([jsonString], { type: 'application/json' });
  } catch (e) {
      console.error("Export Error:", e);
      throw new Error("데이터 내보내기 중 오류가 발생했습니다.");
  }
};

export const mergeActiveDataFromFile = async (file: File): Promise<{ mergedDefects: DefectItem[], newLocations: string[] }> => {
  try {
      const text = await file.text();
      let parsed;
      try {
          parsed = JSON.parse(text);
      } catch (e) {
          throw new Error("파일을 읽을 수 없습니다. 올바른 JSON 파일인지 확인해주세요.");
      }

      if (parsed.type !== 'DOUBLECHECK_TEAM_DATA') {
        throw new Error("이 앱에서 생성된 데이터 파일이 아닙니다.");
      }

      const importedDefectsRaw = parsed.defects || [];
      const newLocations: string[] = [];

      const restoredDefects = await Promise.all(importedDefectsRaw.map(async (d: any) => {
         const newId = generateUniqueId();

         const farPhotos = await Promise.all((d.farPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         const nearPhotos = await Promise.all((d.nearPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         if (d.location && typeof d.location === 'string') {
             newLocations.push(d.location);
         }

         return {
             ...d,
             id: newId,
             farPhotos,
             nearPhotos,
             timestamp: d.timestamp || Date.now()
         };
      }));

      return {
          mergedDefects: restoredDefects,
          newLocations: [...new Set(newLocations)]
      };

  } catch (err: any) {
      console.error("Merge Error:", err);
      throw new Error(err.message || "데이터 합치기에 실패했습니다.");
  }
};

export const exportArchiveData = async () => {
  const archive = await loadArchive();

  const fullArchive = await Promise.all(archive.map(async (item: any) => {
    let defects = item.defects;

    if (!defects || defects.length === 0) {
        const detail = await loadArchivedItemDetail(item.id);
        if (detail) {
            defects = await Promise.all(detail.defects.map(async (d: any) => ({
                ...d,
                farPhotos: await Promise.all(d.farPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
                nearPhotos: await Promise.all(d.nearPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
            })));
        } else {
            defects = [];
        }
    }

    const serializableDefects = await Promise.all(defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b: Blob) => blobToBase64(b))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b: Blob) => blobToBase64(b)))
    })));

    return { ...item, defects: serializableDefects };
  }));

  return JSON.stringify(fullArchive);
};

export const importArchiveData = async (jsonString: string) => {
  const parsedArchive = JSON.parse(jsonString);

  for (const item of parsedArchive) {
    const newId = generateUniqueId();

    const restoredDefects = await Promise.all(item.defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b64: string) => base64ToBlob(b64))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b64: string) => base64ToBlob(b64)))
    })));

    const dataKey = getDataKey(newId);
    await set(dataKey, { 
        defects: restoredDefects, 
        locations: item.locations || [] 
    });

    const indexItem: CompletedInspection = {
        id: newId,
        info: item.info,
        defects: [], 
        locations: [], 
        savedAt: item.savedAt || Date.now(),
        defectCount: restoredDefects.length
    };

    let currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
    if (!Array.isArray(currentArchive)) currentArchive = [];
    await set(KEYS.ARCHIVE, [indexItem, ...currentArchive]);
  }

  return loadArchive();
};

