import React, { useEffect, useState } from 'react';
import { loadSnapshots, deleteSnapshot } from '../services/storage';
import { Snapshot } from '../types';
import { History, Clock, Trash2, ArrowRight, RotateCcw } from 'lucide-react';

interface SnapshotModalProps {
  onClose: () => void;
  onRestore: (snapshot: Snapshot) => void;
}

const SnapshotModal: React.FC<SnapshotModalProps> = ({ onClose, onRestore }) => {
  const [snapshots, setSnapshots] = useState<Snapshot[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadSnapshots().then(data => {
      setSnapshots(data);
      setLoading(false);
    });
  }, []);

  const handleDelete = async (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (confirm('이 임시 저장본을 삭제하시겠습니까?')) {
        const newData = await deleteSnapshot(id);
        setSnapshots(newData);
    }
  };

  const handleRestore = (snapshot: Snapshot) => {
    if (confirm('이 시점으로 복원하시겠습니까?\n현재 작성 중인 내용은 덮어씌워집니다.')) {
        onRestore(snapshot);
    }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 animate-in fade-in" onClick={onClose}>
      <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-xl relative max-h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
        <div className="flex items-center gap-3 mb-4 text-brand-700">
            <div className="bg-brand-100 p-2 rounded-full">
                <History size={24} />
            </div>
            <div>
                <h3 className="text-lg font-bold text-gray-900">임시 보관함 (자동저장)</h3>
                <p className="text-xs text-gray-500">10분마다 자동으로 상태가 저장됩니다.</p>
            </div>
        </div>

        <div className="flex-1 overflow-y-auto space-y-3 pr-1">
            {loading ? (
                <div className="text-center py-8 text-gray-400">로딩 중...</div>
            ) : snapshots.length === 0 ? (
                <div className="text-center py-8 text-gray-400 bg-gray-50 rounded-xl border border-dashed">
                    저장된 내역이 없습니다.
                </div>
            ) : (
                snapshots.map((snap) => (
                    <div 
                        key={snap.id} 
                        className="bg-white border border-gray-200 rounded-xl p-4 shadow-sm active:bg-gray-50 transition cursor-pointer group"
                        onClick={() => handleRestore(snap)}
                    >
                        <div className="flex justify-between items-start">
                            <div className="flex items-center gap-2 text-brand-600 font-bold mb-1">
                                <Clock size={14} />
                                {new Date(snap.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                            </div>
                            <button 
                                onClick={(e) => handleDelete(snap.id, e)}
                                className="text-gray-300 hover:text-red-500 p-1 rounded-full"
                            >
                                <Trash2 size={14} />
                            </button>
                        </div>
                        <div className="text-sm text-gray-700 font-medium">
                            {snap.info.apartmentName} {snap.info.unit}
                        </div>
                        <div className="flex justify-between items-center mt-2 text-xs text-gray-500">
                            <span>하자 {snap.defects.length}건 · 구역 {snap.locations.length}개</span>
                            <span className="flex items-center text-brand-600 font-bold opacity-0 group-hover:opacity-100 transition-opacity">
                                복원 <RotateCcw size={12} className="ml-1"/>
                            </span>
                        </div>
                    </div>
                ))
            )}
        </div>

        <button 
            onClick={onClose} 
            className="w-full mt-4 py-3 bg-gray-100 text-gray-700 font-bold rounded-xl hover:bg-gray-200 transition"
        >
            닫기
        </button>
      </div>
    </div>
  );
};

export default SnapshotModal;

import React, { useState, useEffect, useRef } from 'react';
import InfoForm from './components/InfoForm';
import CaptureScreen from './components/CaptureScreen';
import ArchiveScreen from './components/ArchiveScreen';
import LoginScreen from './components/LoginScreen';
import SnapshotModal from './components/SnapshotModal';
import { AppState, InspectionInfo, DefectItem, Snapshot } from './types';
import { generatePDF, getMatchingStandard } from './services/pdfService';
import { 
  loadStep, loadInfo, loadDefects, loadLocations, 
  saveStep, saveInfo, saveDefects, saveLocations, clearAllData, saveToArchive, checkAuth, clearAuth, updateAuthTimestamp,
  saveSnapshot, loadLogo
} from './services/storage';
import { ArrowLeft, FileText, Download, MapPin, Loader2, Archive, Copy, CheckCircle, RotateCcw, Wifi, WifiOff, LogOut, History } from 'lucide-react';
import { AnimatePresence } from 'framer-motion';
import PhotoViewer from './components/PhotoViewer';

const getLocalISOString = () => {
  const now = new Date();
  const offsetMs = now.getTimezoneOffset() * 60 * 1000;
  // Round to nearest 10 minutes
  const coeff = 1000 * 60 * 10;
  const rounded = new Date(Math.round(now.getTime() / coeff) * coeff);
  const localISOTime = (new Date(rounded.getTime() - offsetMs)).toISOString().slice(0, 16);
  return localISOTime;
};

const INITIAL_INFO: InspectionInfo = {
  apartmentName: '',
  unit: '',
  typeSize: '',
  inspectorName: '',
  phoneNumber: '',
  date: getLocalISOString()
};

// Default categories for 84sqm apartment
const DEFAULT_LOCATIONS = [
  '현관', '현관창고', '공용욕실', '침실3', '침실2', '복도', 
  '펜트리', '거실', '주방', '다용도실', '침실1', '발코니', 
  '실외기실', '대피공간', '드레스룸', '부부욕실'
];

const App: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthorized, setIsAuthorized] = useState(false); // Auth State

  const [step, setStep] = useState<AppState['step']>('info');
  // Track the previous step to allow returning from Archive
  const [lastStep, setLastStep] = useState<AppState['step']>('info');

  const [info, setInfo] = useState<InspectionInfo>(INITIAL_INFO);
  const [defects, setDefects] = useState<DefectItem[]>([]);
  const [locations, setLocations] = useState<string[]>(DEFAULT_LOCATIONS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [showFinishModal, setShowFinishModal] = useState(false);
  const [showSnapshotModal, setShowSnapshotModal] = useState(false);

  // Custom Logo State
  const [logoUrl, setLogoUrl] = useState<string | null>(null);

  // Network Status State
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Photo Viewer State for Preview
  const [viewerState, setViewerState] = useState<{
    isOpen: boolean;
    photos: string[];
    index: number;
  }>({ isOpen: false, photos: [], index: 0 });

  // Use a ref to track if initial load is done to prevent overwriting storage with initial empty state
  const isLoadedRef = useRef(false);

  // Initialize app: Load data from IndexedDB
  useEffect(() => {
    const initApp = async () => {
      try {
        // 1. Check Auth (Validation only)
        const hasAuth = checkAuth();
        setIsAuthorized(hasAuth);

        // 2. Load Data (Always load, even if auth fails, so data is ready upon relogin)
        const [savedStep, savedInfo, savedDefects, savedLocations, savedLogo] = await Promise.all([
          loadStep(),
          loadInfo(),
          loadDefects(),
          loadLocations(),
          loadLogo()
        ]);

        if (savedStep) setStep(savedStep);
        if (savedInfo) setInfo(savedInfo);
        if (savedDefects) setDefects(savedDefects);
        if (savedLocations) setLocations(savedLocations);
        if (savedLogo) setLogoUrl(savedLogo);

      } catch (error) {
        console.error("Failed to load saved data", error);
      } finally {
        setIsLoading(false);
        isLoadedRef.current = true;
      }
    };

    initApp();
  }, []);

  // Monitor App Visibility (Background/Foreground)
  useEffect(() => {
    const handleVisibilityChange = () => {
      // When app comes back to foreground
      if (document.visibilityState === 'visible') {
        const isValid = checkAuth();
        // If timed out or session lost, force logout
        if (!isValid) {
          setIsAuthorized(false);
        } else {
          // If valid, just ensure state matches
          setIsAuthorized(true);
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, []);

  // Monitor User Activity to Refresh Session (Prevent timeout while working)
  useEffect(() => {
    if (!isAuthorized) return;

    const handleUserActivity = () => {
      updateAuthTimestamp();
    };

    // Listen to common interaction events
    window.addEventListener('click', handleUserActivity);
    window.addEventListener('touchstart', handleUserActivity);
    window.addEventListener('keydown', handleUserActivity);

    return () => {
      window.removeEventListener('click', handleUserActivity);
      window.removeEventListener('touchstart', handleUserActivity);
      window.removeEventListener('keydown', handleUserActivity);
    };
  }, [isAuthorized]);

  // Monitor Network Status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- AUTO-SAVE SNAPSHOT LOGIC ---
  useEffect(() => {
    if (!isLoadedRef.current || step !== 'capture') return;

    const snapshotInterval = setInterval(() => {
        // Only save snapshot if there is meaningful data
        if (defects.length > 0) {
            saveSnapshot(info, defects, locations).catch(err => console.error("Auto-save failed", err));
        }
    }, 10 * 60 * 1000); // 10 minutes

    return () => clearInterval(snapshotInterval);
  }, [step, info, defects, locations]);
  // -------------------------------

  // Prevent accidental back navigation
  useEffect(() => {
    // Push current state to history to create a buffer
    history.pushState(null, '', window.location.href);

    const handlePopState = () => {
      // When back button is pressed, push state again to stay on page
      history.pushState(null, '', window.location.href);
    };

    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  // Persist state changes
  useEffect(() => {
    if (isLoadedRef.current) saveStep(step);
  }, [step]);

  useEffect(() => {
    if (isLoadedRef.current) saveInfo(info);
  }, [info]);

  useEffect(() => {
    if (isLoadedRef.current) saveDefects(defects);
  }, [defects]);

  useEffect(() => {
    if (isLoadedRef.current) saveLocations(locations);
  }, [locations]);

  const handleInfoSubmit = (data: InspectionInfo) => {
    setInfo(data);
    setStep('capture');
  };

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    setTimeout(async () => {
      // Re-load logo just in case it was updated in storage
      const currentLogo = await loadLogo();
      await generatePDF(info, defects, currentLogo);
      setIsGenerating(false);
    }, 100);
  };

  const handleCopyText = () => {
    if (defects.length === 0) {
      alert('복사할 하자 내역이 없습니다.');
      return;
    }

    const dateStr = new Date(info.date).toLocaleString('ko-KR');

    let text = `[사전점검 리포트 - Double Check]\n\n`;
    text += `■ 현장 정보\n`;
    text += `- 현장명: ${info.apartmentName}\n`;
    text += `- 호수: ${info.unit}\n`;
    text += `- 타입: ${info.typeSize}\n`;
    text += `- 고객명: ${info.inspectorName} (${info.phoneNumber})\n`;
    text += `- 점검일: ${dateStr}\n`;
    text += `\n================================\n\n`;
    text += `■ 하자 세부 내역 (총 ${defects.length}건)\n\n`;

    // Group by location
    const grouped = defects.reduce((acc, d) => {
      (acc[d.location] = acc[d.location] || []).push(d);
      return acc;
    }, {} as Record<string, DefectItem[]>);

    // Sort locations by their order in the locations array
    const sortedLocs = locations.filter(loc => grouped[loc]);

    sortedLocs.forEach(loc => {
      text += `[${loc}]\n`;
      grouped[loc].forEach((d, i) => {
        text += `${i + 1}. ${d.description}\n`;
      });
      text += '\n';
    });

    navigator.clipboard.writeText(text).then(() => {
      alert('고객 정보와 하자 내역이 모두 복사되었습니다.');
    }).catch(err => {
      console.error('Failed to copy: ', err);
      alert('텍스트 복사에 실패했습니다.');
    });
  };

  const handleCompleteClick = () => {
    setShowFinishModal(true);
  };

  const confirmCompleteAndArchive = async () => {
    setShowFinishModal(false);
    setIsLoading(true);

    try {
      // 1. Archive current data
      await saveToArchive(info, defects, locations);

      // 2. Clear active data
      await clearAllData();
      localStorage.removeItem('info_form_draft');

      // 3. Reset State
      setInfo({ ...INITIAL_INFO, date: getLocalISOString() });
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setStep('info');

      alert('저장이 완료되었습니다. 보관함에서 언제든지 내역을 확인하고 수정할 수 있습니다.');
    } catch (e) {
      console.error(e);
      alert('저장 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = async () => {
    if (confirm('모든 데이터가 초기화됩니다 (보관되지 않음). 처음으로 돌아가시겠습니까?')) {
      setIsLoading(true);
      await clearAllData();
      setStep('info');
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setInfo(INITIAL_INFO);
      localStorage.removeItem('info_form_draft'); 
      isLoadedRef.current = true;
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    if (confirm('보안을 위해 앱을 잠그시겠습니까?')) {
      clearAuth();
      setIsAuthorized(false);
    }
  };

  const handleLoadArchive = (archivedInfo: InspectionInfo, archivedDefects: DefectItem[], archivedLocations: string[]) => {
    setInfo(archivedInfo);
    setDefects(archivedDefects);
    setLocations(archivedLocations);
    setStep('preview'); // Go straight to preview to check/download
  };

  const handleRestoreSnapshot = (snapshot: Snapshot) => {
     setInfo(snapshot.info);
     setDefects(snapshot.defects);
     setLocations(snapshot.locations);
     setShowSnapshotModal(false);
     setStep('capture'); // Go to capture screen to continue work
  };

  const openPhotoViewer = (photos: string[], index: number) => {
    setViewerState({
      isOpen: true,
      photos,
      index
    });
  };

  // Group defects by location for preview
  const groupedDefects = defects.reduce((acc, defect) => {
