export default App;

import { get, set, del, clear } from 'idb-keyval';
import { DefectItem, InspectionInfo, AppState, CompletedInspection, Snapshot } from '../types';

const KEYS = {
  STEP: 'app_step',
  INFO: 'app_info',
  DEFECTS: 'app_defects',
  LOCATIONS: 'app_locations',
  DRAFT: 'app_draft',
  ARCHIVE: 'app_archive',
  SNAPSHOTS: 'app_snapshots', // New: Temp Archive
  // Logo key removed
  // Auth keys
  AUTH_TIMESTAMP: 'app_auth_last_active' // LocalStorage (Time check)
};

const SESSION_KEY = 'app_session_active'; // SessionStorage (App kill check)
// Changed back to 1 Hour (Security Requirement)
const AUTH_TIMEOUT = 60 * 60 * 1000; 

// --- Auth Helpers ---

// Login: Set both session flag (cleared on app close) and timestamp (for timeout)
export const saveAuth = () => {
  sessionStorage.setItem(SESSION_KEY, 'true');
  localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
};

// Check Auth: Must have Session AND (Current Time - Last Active < Timeout)
export const checkAuth = (): boolean => {
  // 1. Check if App was killed/closed (SessionStorage is cleared on browser/tab close)
  // We prioritize the timestamp check for the "1 hour inactivity" rule.

  const lastActiveStr = localStorage.getItem(KEYS.AUTH_TIMESTAMP);
  if (!lastActiveStr) {
    return false; 
  }

  const lastActive = parseInt(lastActiveStr, 10);
  const now = Date.now();

  if (now - lastActive > AUTH_TIMEOUT) {
    // Timeout expired (1 Hour)
    clearAuth();
    return false;
  }

  // 2. If valid, we do NOT automatically update timestamp here. 
  // Timestamp update should happen only on user interaction (handled in App.tsx).

  // Ensure session key exists if timestamp is valid (for PWA consistency)
  if (!sessionStorage.getItem(SESSION_KEY)) {
      sessionStorage.setItem(SESSION_KEY, 'true');
  }

  return true;
};

// Refresh the timer (called on user interaction)
export const updateAuthTimestamp = () => {
  localStorage.setItem(KEYS.AUTH_TIMESTAMP, Date.now().toString());
};

export const clearAuth = () => {
  sessionStorage.removeItem(SESSION_KEY);
  localStorage.removeItem(KEYS.AUTH_TIMESTAMP);
};

// --- Basic Data Access ---
export const saveStep = (step: AppState['step']) => set(KEYS.STEP, step);
export const saveInfo = (info: InspectionInfo) => set(KEYS.INFO, info);
export const saveLocations = (locations: string[]) => set(KEYS.LOCATIONS, locations);

export const loadStep = () => get<AppState['step']>(KEYS.STEP);
export const loadInfo = () => get<InspectionInfo>(KEYS.INFO);
export const loadLocations = () => get<string[]>(KEYS.LOCATIONS);

// --- Handle Defects with Blobs ---
export const saveDefects = async (defects: DefectItem[]) => {
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      })),
      nearPhotos: await Promise.all(d.nearPhotos.map(async (url) => {
        const res = await fetch(url);
        return await res.blob();
      }))
    }))
  );
  await set(KEYS.DEFECTS, defectsWithBlobs);
};

export const loadDefects = async (): Promise<DefectItem[]> => {
  const saved = await get<any[]>(KEYS.DEFECTS);
  if (!saved) return [];
  return saved.map((d) => ({
    ...d,
    farPhotos: d.farPhotos.map((blob: Blob) => URL.createObjectURL(blob)),
    nearPhotos: d.nearPhotos.map((blob: Blob) => URL.createObjectURL(blob))
  }));
};

// --- Draft Handling ---
export const saveDraft = async (data: {
  location: string;
  farPhotos: string[];
  nearPhotos: string[];
  description: string;
  editingId: string | null;
}) => {
  const farBlobs = await Promise.all(data.farPhotos.map(url => fetch(url).then(r => r.blob())));
  const nearBlobs = await Promise.all(data.nearPhotos.map(url => fetch(url).then(r => r.blob())));
  await set(KEYS.DRAFT, { ...data, farPhotos: farBlobs, nearPhotos: nearBlobs });
};

export const loadDraft = async () => {
  const draft = await get<any>(KEYS.DRAFT);
  if (!draft) return null;
  return {
    ...draft,
    farPhotos: draft.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: draft.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
  };
};

export const clearDraft = () => del(KEYS.DRAFT);

export const clearAllData = async () => {
  // CRITICAL: Only clear active session data. 
  // NEVER clear ARCHIVE or SNAPSHOTS here.
  await del(KEYS.STEP);
  await del(KEYS.INFO);
  await del(KEYS.DEFECTS);
  await del(KEYS.LOCATIONS);
  await del(KEYS.DRAFT);
};

// --- SNAPSHOTS (Temp Archive) ---
const MAX_SNAPSHOTS = 6; // Keep last 1 hour (if 10 min interval)

export const saveSnapshot = async (info: InspectionInfo, defects: DefectItem[], locations: string[]) => {
  try {
    let snapshots = await get<any[]>(KEYS.SNAPSHOTS) || [];

    // Convert defect photos to blobs for storage
    const defectsWithBlobs = await Promise.all(
      defects.map(async (d) => ({
        ...d,
        farPhotos: await Promise.all(d.farPhotos.map(url => fetch(url).then(r => r.blob()))),
        nearPhotos: await Promise.all(d.nearPhotos.map(url => fetch(url).then(r => r.blob())))
      }))
    );

    const newSnapshot = {
      id: Date.now().toString(),
      timestamp: Date.now(),
      info,
      defects: defectsWithBlobs,
      locations
    };

    // Add to beginning, slice to max
    snapshots = [newSnapshot, ...snapshots].slice(0, MAX_SNAPSHOTS);
    await set(KEYS.SNAPSHOTS, snapshots);
  } catch (e) {
    console.error("Failed to save snapshot", e);
  }
};

export const loadSnapshots = async (): Promise<Snapshot[]> => {
  const saved = await get<any[]>(KEYS.SNAPSHOTS);
  if (!saved) return [];

  // Convert blobs back to URLs
  return saved.map(s => ({
    ...s,
    defects: s.defects.map((d: any) => ({
      ...d,
      farPhotos: d.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
      nearPhotos: d.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
    }))
  }));
};

export const deleteSnapshot = async (id: string) => {
  const snapshots = await get<Snapshot[]>(KEYS.SNAPSHOTS) || [];
  const newSnapshots = snapshots.filter(s => s.id !== id);
  await set(KEYS.SNAPSHOTS, newSnapshots);
  return newSnapshots;
};

// --- Archive Handling (Optimized for High Capacity) ---

const getDataKey = (id: string) => `archive_data_${id}`;

export const saveToArchive = async (info: InspectionInfo, defects: DefectItem[], locations: string[]) => {
  const id = Date.now().toString();
  const dataKey = getDataKey(id);

  // 1. Prepare Heavy Data (Defects with Blobs)
  const defectsWithBlobs = await Promise.all(
    defects.map(async (d) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map(url => fetch(url).then(r => r.blob()))),
      nearPhotos: await Promise.all(d.nearPhotos.map(url => fetch(url).then(r => r.blob())))
    }))
  );

  // Save heavy data separately in IndexedDB (Persistent)
  await set(dataKey, { defects: defectsWithBlobs, locations });

  // 2. Prepare Index Item (Lightweight)
  const indexItem: CompletedInspection = {
    id,
    info,
    defects: [], // Empty to save memory in the list
    locations: [], // Empty to save memory
    savedAt: Date.now(),
    defectCount: defects.length
  };

  let currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  if (!Array.isArray(currentArchive)) currentArchive = [];

  // Add new item to the top
  await set(KEYS.ARCHIVE, [indexItem, ...currentArchive]);
};

export const loadArchive = async (): Promise<CompletedInspection[]> => {
  const archive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  return Array.isArray(archive) ? archive : [];
};

export const loadArchivedItemDetail = async (id: string) => {
  const dataKey = getDataKey(id);
  const data = await get<any>(dataKey);

  if (data) {
     const defects = data.defects.map((d: any) => ({
        ...d,
        farPhotos: d.farPhotos.map((b: Blob) => URL.createObjectURL(b)),
        nearPhotos: d.nearPhotos.map((b: Blob) => URL.createObjectURL(b))
     }));
     return { defects, locations: data.locations };
  }
  return null;
};

export const restoreArchivedItemLegacy = (item: any): { defects: DefectItem[] } => {
  if (!item || !item.defects) return { defects: [] };
  const restoredDefects = item.defects.map((d: any) => ({
    ...d,
    farPhotos: (d.farPhotos || []).map((b: Blob) => URL.createObjectURL(b)),
    nearPhotos: (d.nearPhotos || []).map((b: Blob) => URL.createObjectURL(b))
  }));
  return { defects: restoredDefects };
};

export const deleteFromArchive = async (id: string) => {
  const currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
  if (!currentArchive) return [];

  const newArchive = currentArchive.filter(item => item.id !== id);
  await set(KEYS.ARCHIVE, newArchive);

  await del(getDataKey(id));

  return newArchive;
};

// --- TEAM COLLABORATION / EXPORT ---

const blobToBase64 = (blob: Blob): Promise<string> => {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
        const result = reader.result as string;
        resolve(result);
    };
    reader.onerror = (e) => reject(e);
    reader.readAsDataURL(blob);
  });
};

const base64ToBlob = async (base64: string): Promise<Blob> => {
  try {
      const res = await fetch(base64);
      return await res.blob();
  } catch (e) {
      console.error("Error converting base64 to blob", e);
      throw new Error("이미지 변환 실패");
  }
};

const generateUniqueId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substring(2, 5);
};

export const exportActiveDataToDataFile = async (info: InspectionInfo, defects: DefectItem[]): Promise<Blob> => {
  try {
      const serializableDefects = await Promise.all(defects.map(async (d) => {
        const farPhotosB64 = await Promise.all(d.farPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));
        const nearPhotosB64 = await Promise.all(d.nearPhotos.map(async url => {
            const blob = await (await fetch(url)).blob();
            return blobToBase64(blob);
        }));

        return {
            ...d,
            farPhotos: farPhotosB64,
            nearPhotos: nearPhotosB64
        };
      }));

      const data = {
        version: '2.0',
        type: 'DOUBLECHECK_TEAM_DATA',
        info,
        defects: serializableDefects,
        exportedAt: Date.now()
      };

      const jsonString = JSON.stringify(data);
      return new Blob([jsonString], { type: 'application/json' });
  } catch (e) {
      console.error("Export Error:", e);
      throw new Error("데이터 내보내기 중 오류가 발생했습니다.");
  }
};

export const mergeActiveDataFromFile = async (file: File): Promise<{ mergedDefects: DefectItem[], newLocations: string[] }> => {
  try {
      const text = await file.text();
      let parsed;
      try {
          parsed = JSON.parse(text);
      } catch (e) {
          throw new Error("파일을 읽을 수 없습니다. 올바른 JSON 파일인지 확인해주세요.");
      }

      if (parsed.type !== 'DOUBLECHECK_TEAM_DATA') {
        throw new Error("이 앱에서 생성된 데이터 파일이 아닙니다.");
      }

      const importedDefectsRaw = parsed.defects || [];
      const newLocations: string[] = [];

      const restoredDefects = await Promise.all(importedDefectsRaw.map(async (d: any) => {
         const newId = generateUniqueId();

         const farPhotos = await Promise.all((d.farPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         const nearPhotos = await Promise.all((d.nearPhotos || []).map(async (b64: string) => {
             const blob = await base64ToBlob(b64);
             return URL.createObjectURL(blob);
         }));

         if (d.location && typeof d.location === 'string') {
             newLocations.push(d.location);
         }

         return {
             ...d,
             id: newId,
             farPhotos,
             nearPhotos,
             timestamp: d.timestamp || Date.now()
         };
      }));

      return {
          mergedDefects: restoredDefects,
          newLocations: [...new Set(newLocations)]
      };

  } catch (err: any) {
      console.error("Merge Error:", err);
      throw new Error(err.message || "데이터 합치기에 실패했습니다.");
  }
};

// Updated: Now accepts optional list of IDs to export selectively
export const exportArchiveData = async (selectedIds?: string[]) => {
  let archive = await loadArchive();

  // Filter if selectedIds are provided
  if (selectedIds && selectedIds.length > 0) {
      archive = archive.filter(item => selectedIds.includes(item.id));
  }

  const fullArchive = await Promise.all(archive.map(async (item: any) => {
    let defects = item.defects;

    if (!defects || defects.length === 0) {
        const detail = await loadArchivedItemDetail(item.id);
        if (detail) {
            defects = await Promise.all(detail.defects.map(async (d: any) => ({
                ...d,
                farPhotos: await Promise.all(d.farPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
                nearPhotos: await Promise.all(d.nearPhotos.map((url: string) => fetch(url).then(r => r.blob()))),
            })));
        } else {
            defects = [];
        }
    }

    const serializableDefects = await Promise.all(defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b: Blob) => blobToBase64(b))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b: Blob) => blobToBase64(b)))
    })));

    return { ...item, defects: serializableDefects };
  }));

  return JSON.stringify(fullArchive);
};

export const importArchiveData = async (jsonString: string) => {
  const parsedArchive = JSON.parse(jsonString);

  for (const item of parsedArchive) {
    const newId = generateUniqueId();

    const restoredDefects = await Promise.all(item.defects.map(async (d: any) => ({
      ...d,
      farPhotos: await Promise.all(d.farPhotos.map((b64: string) => base64ToBlob(b64))),
      nearPhotos: await Promise.all(d.nearPhotos.map((b64: string) => base64ToBlob(b64)))
    })));

    const dataKey = getDataKey(newId);
    await set(dataKey, { 
        defects: restoredDefects, 
        locations: item.locations || [] 
    });

    const indexItem: CompletedInspection = {
        id: newId,
        info: item.info,
        defects: [], 
        locations: [], 
        savedAt: item.savedAt || Date.now(),
        defectCount: restoredDefects.length
    };

    let currentArchive = await get<CompletedInspection[]>(KEYS.ARCHIVE);
    if (!Array.isArray(currentArchive)) currentArchive = [];
    await set(KEYS.ARCHIVE, [indexItem, ...currentArchive]);
  }

  return loadArchive();
};

import React, { useEffect, useState, useRef } from 'react';
import { CompletedInspection } from '../types';
import { loadArchive, deleteFromArchive, loadArchivedItemDetail, restoreArchivedItemLegacy, exportArchiveData, importArchiveData } from '../services/storage';
import { Trash2, Calendar, FileText, ArrowRight, ArrowLeft, RotateCcw, Home, Upload, Download, Loader2, Share2, CheckSquare, Square, X, CheckCircle2, Check, CheckCheck } from 'lucide-react';

interface ArchiveScreenProps {
  onLoad: (info: any, defects: any, locations: any) => void;
  onGoBack: () => void;
  onGoHome: () => void;
}

const ArchiveScreen: React.FC<ArchiveScreenProps> = ({ onLoad, onGoBack, onGoHome }) => {
  const [items, setItems] = useState<CompletedInspection[]>([]);
  const [loading, setLoading] = useState(true);

  // Selection Mode State
  const [isSelectionMode, setIsSelectionMode] = useState(false);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());

  // Modals state
  const [showExitDialog, setShowExitDialog] = useState(false);
  const [itemToDelete, setItemToDelete] = useState<string | null>(null);
  const [itemToRestore, setItemToRestore] = useState<CompletedInspection | null>(null);
  const [processing, setProcessing] = useState(false);

  // File Input Ref for Import
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    loadArchive().then(data => {
      setItems(data);
      setLoading(false);
    });
  }, []);

  // Selection Handlers
  const toggleSelectionMode = () => {
    setIsSelectionMode(!isSelectionMode);
    setSelectedIds(new Set()); // Reset on toggle
  };

  const toggleItemSelection = (id: string) => {
    const newSelected = new Set(selectedIds);
    if (newSelected.has(id)) {
      newSelected.delete(id);
    } else {
      newSelected.add(id);
    }
    setSelectedIds(newSelected);
  };

  const handleSelectAll = () => {
    if (selectedIds.size === items.length) {
      setSelectedIds(new Set());
    } else {
      setSelectedIds(new Set(items.map(i => i.id)));
    }
  };

  const requestDelete = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    setItemToDelete(id);
  };

  const confirmDelete = async () => {
    setProcessing(true);
    try {
      if (itemToDelete) {
        // Single delete
        const newItems = await deleteFromArchive(itemToDelete);
        setItems(newItems);
        setItemToDelete(null);
      } else if (isSelectionMode && selectedIds.size > 0) {
        // Bulk delete
        let currentItems = items;
        for (const id of selectedIds) {
           currentItems = await deleteFromArchive(id);
        }
        setItems(currentItems);
        setIsSelectionMode(false);
        setSelectedIds(new Set());
      }
    } catch (e) {
      console.error("Delete failed", e);
      alert("삭제 중 오류가 발생했습니다.");
    } finally {
      setProcessing(false);
    }
  };

  const requestRestore = (item: CompletedInspection) => {
    if (isSelectionMode) {
      toggleItemSelection(item.id);
    } else {
      setItemToRestore(item);
    }
  };

  const confirmRestore = async () => {
    if (!itemToRestore) return;
    setProcessing(true);
    try {
      // Use setTimeout to allow UI to update (show loading state)
      setTimeout(async () => {
        try {
          let defects = [];
          let locations = [];

          // 1. Try to load detailed data from split storage
          const detail = await loadArchivedItemDetail(itemToRestore.id);

          if (detail) {
            defects = detail.defects;
            locations = detail.locations;
          } else {
            // 2. Fallback: Check if it's a legacy item with data inside the index
            if (itemToRestore.defects && itemToRestore.defects.length > 0) {
               const legacy = restoreArchivedItemLegacy(itemToRestore);
               defects = legacy.defects;
               locations = itemToRestore.locations;
            }
          }

          // Default locations if missing
          if (!locations || !Array.isArray(locations) || locations.length === 0) {
             locations = ['현관', '거실', '주방', '침실1', '침실2', '침실3', '공용욕실', '부부욕실', '발코니', '다용도실'];
          }

          if (defects.length === 0 && (itemToRestore.defectCount || 0) > 0) {
              alert('데이터를 찾을 수 없습니다.');
          } else {
              onLoad(itemToRestore.info, defects, locations);
          }
          setItemToRestore(null); // Close modal
        } catch (e) {
          console.error("Error restoring item:", e);
          alert('데이터를 불러오는 중 오류가 발생했습니다. 데이터가 손상되었을 수 있습니다.');
        } finally {
          setProcessing(false);
        }
      }, 50);
    } catch (e) {
       console.error("Restore outer error", e);
       setProcessing(false);
    }
  };

  const handleBackClick = () => {
    if (isSelectionMode) {
      toggleSelectionMode();
    } else {
      setShowExitDialog(true);
    }
  };

  // --- Export / Import Handlers ---
  const handleExport = async () => {
    // If in selection mode, use selected IDs. Else, export all.
    const idsToExport = isSelectionMode ? Array.from(selectedIds) : undefined;

    if (isSelectionMode && selectedIds.size === 0) {
        alert("선택된 항목이 없습니다.");
        return;
    }

    if (!isSelectionMode && items.length === 0) {
      alert("내보낼 데이터가 없습니다.");
      return;
    }

    setProcessing(true);
    try {
      // Pass the selected IDs to the service function
      const jsonString = await exportArchiveData(idsToExport);
      if (!jsonString) return;

      const blob = new Blob([jsonString], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      const dateStr = new Date().toISOString().split('T')[0];
      const count = idsToExport ? idsToExport.length : items.length;

      link.href = url;
      link.download = `DoubleCheck_Backup_${count}items_${dateStr}.json`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);

      // If success in selection mode, exit selection
      if(isSelectionMode) toggleSelectionMode();

    } catch (e) {
      console.error("Export failed", e);
      alert("데이터 내보내기 실패. 파일 크기가 너무 클 수 있습니다.");
    } finally {
      setProcessing(false);
    }
  };

  const handleImportClick = () => {
    fileInputRef.current?.click();
  };

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setProcessing(true);
    try {
      const text = await file.text();
      const newItems = await importArchiveData(text);
      setItems(newItems); // Update list
      alert("데이터를 성공적으로 가져왔습니다.");
    } catch (err) {
      console.error("Import failed", err);
      alert("데이터 가져오기 실패. 올바른 백업 파일인지 확인해주세요.");
    } finally {
      setProcessing(false);
      // Reset input
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center min-h-[50vh] text-gray-500 gap-2">
        <span className="animate-spin rounded-full h-5 w-5 border-b-2 border-brand-600"></span>
        불러오는 중...
      </div>
    );
  }

  return (
    <div className="bg-white min-h-full pb-32 relative">
      <div className="p-6 border-b border-gray-100 flex justify-between items-start sticky top-0 bg-white/95 backdrop-blur-sm z-20">
        <div>
          <h2 className="text-xl font-bold text-gray-800">
             {isSelectionMode ? `${selectedIds.size}개 선택됨` : '점검 완료 보관함'}
          </h2>
          <p className="text-sm text-gray-500 mt-1">
             {isSelectionMode ? '내보내거나 삭제할 항목을 선택하세요.' : '완료된 점검 내역입니다.'}
          </p>
        </div>
        <div className="flex gap-2">
           {/* Hidden Input for Import */}
           <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            accept=".json" 
            className="hidden" 
          />

          {isSelectionMode ? (
              <button 
                onClick={toggleSelectionMode}
                className="flex flex-col items-center justify-center text-gray-500 hover:text-gray-800 p-2 rounded-lg bg-gray-50 transition"
              >
                  <X size={20} />
                  <span className="text-[10px] font-bold mt-1">취소</span>
              </button>
          ) : (
             <>
                <button 
                    onClick={handleImportClick}
                    disabled={processing}
                    className="flex flex-col items-center justify-center text-gray-600 hover:text-brand-600 p-2 rounded-lg bg-gray-50 hover:bg-brand-50 transition"
                    title="데이터 가져오기 (Merge)"
                >
                    <Download size={20} />
                    <span className="text-[10px] font-bold mt-1">가져오기</span>
                </button>
                <button 
                    onClick={toggleSelectionMode}
                    disabled={items.length === 0}
                    className={`flex flex-col items-center justify-center p-2 rounded-lg transition
                    ${items.length === 0 ? 'text-gray-300 bg-gray-50' : 'text-gray-600 hover:text-brand-600 bg-gray-50 hover:bg-brand-50'}`}
                >
                    <CheckSquare size={20} />
                    <span className="text-[10px] font-bold mt-1">선택</span>
                </button>
             </>
          )}
        </div>
      </div>

      {processing && (
        <div className="absolute top-[80px] left-0 right-0 z-10 bg-brand-50 text-brand-700 text-xs font-bold py-2 text-center animate-pulse">
          데이터 처리 중입니다... 잠시만 기다려주세요.
        </div>
      )}

      <div className="p-4 space-y-3">
        {items.length === 0 ? (
          <div className="text-center py-12 bg-gray-50 rounded-2xl border border-dashed border-gray-200">
            <FileText size={40} className="mx-auto text-gray-300 mb-3" />
            <p className="text-gray-500">보관된 점검 내역이 없습니다.</p>
            <p className="text-xs text-gray-400 mt-2">다른 기기의 데이터를 보려면<br/>상단의 '가져오기'를 사용하세요.</p>
          </div>
        ) : (
          items.map((item) => {
            // Count logic handling both new and legacy data
            const count = item.defectCount !== undefined ? item.defectCount : (item.defects ? item.defects.length : 0);
            const isSelected = selectedIds.has(item.id);

            return (
              <div 
                key={item.id} 
                onClick={() => requestRestore(item)}
                className={`
                    border rounded-xl p-5 shadow-sm transition cursor-pointer relative group flex items-start gap-3
