              <div className="bg-red-100 p-2 rounded-full">
                <Trash2 size={24} />
              </div>
              <h3 className="text-lg font-bold text-gray-900">
                  {itemToDelete === 'BULK' ? `${selectedIds.size}개 항목을 삭제하시겠습니까?` : '삭제하시겠습니까?'}
