const MIN_FAR = 1;
const MAX_FAR = 3;
const MIN_NEAR = 1;
const MAX_NEAR = 10;

// --- Image Compression Utility (Optimized for iOS) ---
const compressImage = async (file: File): Promise<Blob> => {
  // iOS Optimization: Reduce max dimension to 1024px to prevent memory crashes
  const MAX_WIDTH = 1024;
  const MAX_HEIGHT = 1024;
  const QUALITY = 0.6; // Slightly reduced quality for speed

  // Method 1: Ultra-fast Bitmap Decoding (Modern Browsers & iOS 15+)
  // This decodes image off the main thread, preventing UI freeze
  if (window.createImageBitmap) {
    try {
      const bitmap = await window.createImageBitmap(file);
      const canvas = document.createElement('canvas');
      let { width, height } = bitmap;

      // Calculate new dimensions
      if (width > height) {
        if (width > MAX_WIDTH) {
          height = Math.round(height * (MAX_WIDTH / width));
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width = Math.round(width * (MAX_HEIGHT / height));
          height = MAX_HEIGHT;
        }
      }

      canvas.width = width;
      canvas.height = height;

      const ctx = canvas.getContext('2d');
      if (ctx) {
         ctx.drawImage(bitmap, 0, 0, width, height);
         // Cleanup bitmap memory immediately
         bitmap.close(); 

         return new Promise((resolve, reject) => {
            canvas.toBlob((blob) => {
               if (blob) resolve(blob);
               else reject(new Error("Blob creation failed"));
            }, 'image/jpeg', QUALITY);
         });
      }
    } catch (e) {
      console.warn("Bitmap compression failed, falling back to legacy", e);
    }
  }

  // Method 2: Fallback for older devices or incompatible files
  return new Promise((resolve, reject) => {
    const img = new Image();
    const url = URL.createObjectURL(file);
    img.src = url;

    img.onload = () => {
      const canvas = document.createElement('canvas');
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > MAX_WIDTH) {
          height = Math.round(height * (MAX_WIDTH / width));
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width = Math.round(width * (MAX_HEIGHT / height));
          height = MAX_HEIGHT;
        }
      }

      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        ctx.drawImage(img, 0, 0, width, height);
        canvas.toBlob((blob) => {
          URL.revokeObjectURL(url);
          if (blob) resolve(blob);
          else reject(new Error("Compression failed"));
        }, 'image/jpeg', QUALITY);
      } else {
        URL.revokeObjectURL(url);
        reject(new Error("Canvas context missing"));
      }
    };
    img.onerror = (err) => {
      URL.revokeObjectURL(url);
      reject(err);
    };
  });
};

// --- Auto Save/Download Utility ---
const saveToDevice = (file: File | Blob, prefix: string) => {
  try {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url;
    // Format: DC_Far_240501_123456_789.jpg (Add milliseconds to prevent overwriting/skipping)
    const now = new Date();
    const timestamp = now.toISOString().replace(/[-:T.]/g, '').slice(2, 14);
    const millis = String(now.getMilliseconds()).padStart(3, '0');

    a.download = `DC_${prefix}_${timestamp}_${millis}.jpg`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 1000); // Extended timeout for iOS
  } catch (e) {
    console.error("Auto-save failed", e);
  }
};

// Custom Sortable Item for Grid Layout
const SortableItem: React.FC<{ 
  loc: string, 
  active: boolean, 
  draggingLoc: string | null,
  onDragStart: (loc: string) => void,
  onDragEnd: () => void,
  onDragTrigger: (e: any, info: PanInfo, loc: string) => void
}> = ({ loc, active, draggingLoc, onDragStart, onDragEnd, onDragTrigger }) => {
  const controls = useDragControls();

  return (
    <motion.div
      layout
      data-loc={loc}
      initial={false}
      animate={{
        scale: draggingLoc === loc ? 1.08 : 1,
        zIndex: draggingLoc === loc ? 100 : 0,
        boxShadow: draggingLoc === loc ? "0px 10px 20px rgba(0,0,0,0.2)" : "0px 1px 2px rgba(0,0,0,0.05)"
      }}
      drag
      dragControls={controls}
      dragListener={false} // Only handle triggers drag
      dragElastic={0.1}
      dragMomentum={false}
      onDragStart={() => onDragStart(loc)}
      onDragEnd={onDragEnd}
      onDrag={(e, info) => onDragTrigger(e, info, loc)}
      className={`
        bg-white rounded-xl border shadow-sm flex flex-col items-center justify-center 
        select-none h-20 p-2 relative overflow-hidden transition-colors
        ${active ? 'border-brand-500 ring-2 ring-brand-500 bg-brand-50' : 'border-gray-200 hover:border-brand-300'}
      `}
    >
      <div className="flex-1 flex flex-col items-center justify-center w-full min-w-0">
        <div className={`p-1.5 rounded-full mb-1 ${active ? 'bg-brand-100 text-brand-600' : 'bg-gray-100 text-gray-500'}`}>
           <MapPin size={16}/>
        </div>
        <span className={`font-bold truncate text-xs w-full text-center ${active ? 'text-brand-800' : 'text-gray-700'}`}>{loc}</span>
      </div>

      {/* Drag Handle */}
      <div 
        className="absolute top-0 right-0 p-2 cursor-grab active:cursor-grabbing text-gray-300 hover:text-gray-500 touch-none"
        onPointerDown={(e) => controls.start(e)}
      >
        <GripVertical size={16} />
      </div>
    </motion.div>
  );
};

const CaptureScreen: React.FC<CaptureScreenProps> = ({ 
  defects, 
  setDefects, 
  locations,
  setLocations,
  onFinish 
}) => {
  const [activeLocation, setActiveLocation] = useState<string>(locations[0]);
  const [isCreating, setIsCreating] = useState(false);
  const [isAddingLocation, setIsAddingLocation] = useState(false);
  const [isReordering, setIsReordering] = useState(false);
  const [newLocationName, setNewLocationName] = useState('');

  const [showTeamModal, setShowTeamModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMsg, setProcessingMsg] = useState('');
  const [isCompressing, setIsCompressing] = useState(false); // Image processing state

  const [preparedFile, setPreparedFile] = useState<{file: File, type: 'JSON' | 'PDF'} | null>(null);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [tempFarPhotos, setTempFarPhotos] = useState<string[]>([]);
  const [tempNearPhotos, setTempNearPhotos] = useState<string[]>([]);
  const [description, setDescription] = useState('');

  const cameraInputFarRef = useRef<HTMLInputElement>(null);
  const galleryInputFarRef = useRef<HTMLInputElement>(null);
  const cameraInputNearRef = useRef<HTMLInputElement>(null);
  const galleryInputNearRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Dragging State
  const [draggingLoc, setDraggingLoc] = useState<string | null>(null);

  const [viewerState, setViewerState] = useState<{
    isOpen: boolean;
    photos: string[];
    index: number;
  }>({ isOpen: false, photos: [], index: 0 });

  const currentLocationDefects = defects.filter(d => d.location === activeLocation);

  useEffect(() => {
    const restoreDraft = async () => {
      try {
        const draft = await loadDraft();
        if (draft) {
          if (!locations.includes(draft.location)) {
            setLocations(prev => [...prev, draft.location]);
          }
          setActiveLocation(draft.location);
          setTempFarPhotos(draft.farPhotos);
          setTempNearPhotos(draft.nearPhotos);
          setDescription(draft.description);
          setEditingId(draft.editingId);
          setIsCreating(true);
        }
      } catch (e) {
        console.error("Failed to restore draft", e);
      }
    };
    restoreDraft();
  }, []);

  useEffect(() => {
    if (!isCreating) return;
    const timer = setTimeout(() => {
      if (!editingId && tempFarPhotos.length === 0 && tempNearPhotos.length === 0 && !description) return;
      saveDraft({
        location: activeLocation,
        farPhotos: tempFarPhotos,
        nearPhotos: tempNearPhotos,
        description,
        editingId
      });
    }, 500);
    return () => clearTimeout(timer);
  }, [isCreating, activeLocation, tempFarPhotos, tempNearPhotos, description, editingId]);

  const resetForm = async () => {
    await clearDraft();
    setTempFarPhotos([]);
    setTempNearPhotos([]);
    setDescription('');
    setEditingId(null);
    setIsCreating(false);
  };

  const handleStartCreation = () => {
    setTempFarPhotos([]);
    setTempNearPhotos([]);
    setDescription('');
    setEditingId(null);
    setIsCreating(true);
  };

  const handleStartEdit = (defect: DefectItem) => {
    setTempFarPhotos([...defect.farPhotos]);
    setTempNearPhotos([...defect.nearPhotos]);
    setDescription(defect.description);
    setEditingId(defect.id);
    setIsCreating(true);
  };

  const handleAddLocation = () => {
    if (newLocationName.trim() && !locations.includes(newLocationName.trim())) {
      const newLoc = newLocationName.trim();
      setLocations([...locations, newLoc]);
      setActiveLocation(newLoc);
      setNewLocationName('');
      setIsAddingLocation(false);
    } else {
      alert('유효한 구역명을 입력해주세요.');
    }
  };

  const handlePhotoAdd = async (e: React.ChangeEvent<HTMLInputElement>, type: 'FAR' | 'NEAR') => {
    const file = e.target.files?.[0];
    if (file) {
      try {
        // Set loading state immediately
        setIsCompressing(true);

        // 1. Save to Device (Async - don't await)
        // Wrapped in setTimeout to prevent UI blocking on iOS immediately
        setTimeout(() => {
           saveToDevice(file, type === 'FAR' ? 'Far' : 'Near');
        }, 0);

        // 2. Process Image
        const compressedBlob = await compressImage(file);
        const url = URL.createObjectURL(compressedBlob);

        // 3. Update State
        if (type === 'FAR') {
          setTempFarPhotos(prev => [...prev, url]);
        } else {
          setTempNearPhotos(prev => [...prev, url]);
        }
      } catch (err) {
        console.error("Image processing error", err);
        // Fallback: If compression fails completely, use original
        try {
           const url = URL.createObjectURL(file);
           if (type === 'FAR') setTempFarPhotos(prev => [...prev, url]);
           else setTempNearPhotos(prev => [...prev, url]);
        } catch(e) {
           alert("사진 처리 중 오류가 발생했습니다.");
        }
      } finally {
        setIsCompressing(false);
      }
    }
    // Clear input to allow re-selecting same file
    e.target.value = '';
  };

  const removePhoto = (type: 'FAR' | 'NEAR', index: number) => {
    if (type === 'FAR') {
      setTempFarPhotos(prev => prev.filter((_, i) => i !== index));
    } else {
      setTempNearPhotos(prev => prev.filter((_, i) => i !== index));
    }
  };

  const handleSaveDefect = async () => {
    if (tempFarPhotos.length < MIN_FAR || tempNearPhotos.length < MIN_NEAR || !description.trim()) {
      alert('필수 사진과 내용을 입력해주세요.');
      return;
    }
    if (editingId) {
      setDefects(prev => prev.map(d => d.id === editingId ? { ...d, farPhotos: tempFarPhotos, nearPhotos: tempNearPhotos, description } : d));
    } else {
      setDefects(prev => [...prev, { id: Date.now().toString(), location: activeLocation, farPhotos: tempFarPhotos, nearPhotos: tempNearPhotos, description, timestamp: Date.now() }]);
    }
    await resetForm();
  };

  const handleDeleteDefect = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (window.confirm('삭제하시겠습니까?')) {
      setDefects(prev => prev.filter(d => d.id !== id));
      if (editingId === id) resetForm();
    }
  };

  const handlePrepareData = async () => {
    if (defects.length === 0) {
      alert('공유할 데이터가 없습니다.');
      return;
    }
    setPreparedFile(null);
    setIsProcessing(true);
    setProcessingMsg('데이터 파일 생성 중...');
    try {
      const info = await loadInfo();
      if (!info) throw new Error("Info missing");

      const dataBlob = await exportActiveDataToDataFile(info, defects);
      const fileName = `DoubleCheck_Data_${info.unit}_${new Date().getHours()}시.json`;
      const file = new File([dataBlob], fileName, { type: 'text/plain' });

      setPreparedFile({ file, type: 'JSON' });
    } catch (e) {
      console.error(e);
      alert('데이터 생성 실패: ' + (e as any).message);
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDownload = () => {
    if (!preparedFile) return;
    const url = URL.createObjectURL(preparedFile.file);
    const a = document.createElement('a');
    a.href = url;
    a.download = preparedFile.file.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 100);

    if (preparedFile.type === 'JSON') {
       alert("파일이 저장되었습니다!\n\n[카카오톡 채팅방] -> [+] -> [파일]을 눌러\n방금 저장된 파일(DoubleCheck_Data...)을 전송하세요.");
    } else {
       alert("PDF 파일이 저장되었습니다.");
    }
  };

  const handleMergeFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!confirm('선택한 파일의 내용을 현재 작성 중인 내용에 합치시겠습니까?')) {
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    setIsProcessing(true);
    setProcessingMsg('데이터 분석 및 병합 중...');

    try {
      const { mergedDefects, newLocations } = await mergeActiveDataFromFile(file);
      setDefects(prev => [...prev, ...mergedDefects]);
      setLocations(prev => {
          const uniqueLocs = new Set([...prev, ...newLocations]);
          return Array.from(uniqueLocs);
      });
      setShowTeamModal(false);
      alert(`성공적으로 합쳐졌습니다!\n- 추가된 하자: ${mergedDefects.length}건`);
    } catch (err: any) {
      console.error(err);
      alert('데이터 가져오기 실패: ' + err.message);
    } finally {
      setIsProcessing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // Custom Drag Handler for Grid Sorting
  const handleDrag = (e: any, { point }: PanInfo, loc: string) => {
    // Find the element currently under the pointer
    const elements = Array.from(document.querySelectorAll('[data-loc]'));
    const target = elements.find(el => {
        if (el.getAttribute('data-loc') === loc) return false;
        const rect = el.getBoundingClientRect();
        return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
    });

    if (target) {
        const targetLoc = target.getAttribute('data-loc');
        if (targetLoc && targetLoc !== loc) {
            const fromIndex = locations.indexOf(loc);
            const toIndex = locations.indexOf(targetLoc);

            if (fromIndex !== -1 && toIndex !== -1 && fromIndex !== toIndex) {
                 const newLocations = [...locations];
                 const [moved] = newLocations.splice(fromIndex, 1);
                 newLocations.splice(toIndex, 0, moved);
                 setLocations(newLocations);
            }
        }
    }
  };

  const renderLocationItem = (loc: string) => {
    const count = defects.filter(d => d.location === loc).length;
    const isActive = activeLocation === loc;
    return (
      <button key={loc} onClick={() => !isReordering && setActiveLocation(loc)} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all border whitespace-nowrap ${isActive ? 'bg-brand-600 text-white border-brand-600 shadow-md' : 'bg-white text-gray-600 border-gray-200'}`}>
        {loc} {count > 0 && <span className="text-[10px] ml-1 opacity-70">({count})</span>}
      </button>
    );
  };

  if (isCreating) {
    const matchingStandard = getMatchingStandard(description);
    const currentIdx = editingId ? defects.findIndex(d => d.id === editingId) + 1 : currentLocationDefects.length + 1;

    return (
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 max-w-md mx-auto relative pb-safe animate-in fade-in zoom-in-95">

        {/* Loading Overlay during Compression */}
        {isCompressing && (
           <div className="absolute inset-0 bg-white/80 z-50 flex flex-col items-center justify-center rounded-2xl backdrop-blur-sm">
              <Loader2 className="animate-spin text-brand-600 mb-2" size={32} />
              <p className="text-xs font-bold text-brand-700">사진 압축 및 저장 중...</p>
           </div>
        )}

        <div className="flex justify-between items-center mb-6 border-b pb-4">
          <div className="flex flex-col">
            <h3 className="text-xl font-bold text-gray-800">{editingId ? '내용 수정' : '하자 등록'}</h3>
            <span className="text-xs text-brand-600 font-bold mt-1">[{activeLocation}] 하자 #{currentIdx}</span>
          </div>
          <button onClick={resetForm} className="text-gray-400 hover:text-gray-600 p-2"><X size={24} /></button>
        </div>

        <input type="file" ref={cameraInputFarRef} onChange={(e) => handlePhotoAdd(e, 'FAR')} accept="image/*" capture="environment" className="hidden" />
        <input type="file" ref={galleryInputFarRef} onChange={(e) => handlePhotoAdd(e, 'FAR')} accept="image/*" className="hidden" />
        <input type="file" ref={cameraInputNearRef} onChange={(e) => handlePhotoAdd(e, 'NEAR')} accept="image/*" capture="environment" className="hidden" />
        <input type="file" ref={galleryInputNearRef} onChange={(e) => handlePhotoAdd(e, 'NEAR')} accept="image/*" className="hidden" />

        <div className="space-y-6">
           <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">원거리 사진 ({tempFarPhotos.length}/{MAX_FAR})</label>
              <div className="grid grid-cols-3 gap-2">
                {tempFarPhotos.map((p, i) => (
                  <div key={i} className="relative aspect-square rounded-lg overflow-hidden border bg-gray-50">
                    <img src={p} className="w-full h-full object-cover" decoding="async" loading="lazy" onClick={() => setViewerState({isOpen: true, photos: tempFarPhotos, index: i})} />
                    <button onClick={() => removePhoto('FAR', i)} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 shadow-sm"><X size={10} /></button>
                  </div>
                ))}
                {tempFarPhotos.length < MAX_FAR && (
                  <button onClick={() => cameraInputFarRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-brand-50 border border-brand-200 text-brand-700 hover:bg-brand-100 transition shadow-sm active:scale-95">
                      <Camera size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">사진 촬영</span>
                  </button>
                )}
                {tempFarPhotos.length < MAX_FAR && (
                  <button onClick={() => galleryInputFarRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100 transition active:scale-95">
                      <ImageIcon size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">앨범</span>
                  </button>
                )}
              </div>
           </div>

           <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">근거리 사진 ({tempNearPhotos.length}/{MAX_NEAR})</label>
              <div className="grid grid-cols-3 gap-2">
                {tempNearPhotos.map((p, i) => (
                  <div key={i} className="relative aspect-square rounded-lg overflow-hidden border bg-gray-50">
                    <img src={p} className="w-full h-full object-cover" decoding="async" loading="lazy" onClick={() => setViewerState({isOpen: true, photos: tempNearPhotos, index: i})} />
                    <button onClick={() => removePhoto('NEAR', i)} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 shadow-sm"><X size={10} /></button>
                  </div>
                ))}
                {tempNearPhotos.length < MAX_NEAR && (
                  <button onClick={() => cameraInputNearRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-brand-50 border border-brand-200 text-brand-700 hover:bg-brand-100 transition shadow-sm active:scale-95">
                      <Camera size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">사진 촬영</span>
                  </button>
                )}
                {tempNearPhotos.length < MAX_NEAR && (
                   <button onClick={() => galleryInputNearRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100 transition active:scale-95">
                      <ImageIcon size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">앨범</span>
                  </button>
                )}
              </div>
           </div>

          <div>
            <div className="flex justify-between items-center mb-2">
              <label className="block text-sm font-bold text-gray-700">하자 내용</label>
              <span className="text-[10px] text-gray-400 font-medium">* 번호 자동 부여됨</span>
            </div>
            <textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="번호 없이 내용만 입력하세요 (예: 벽지 들뜸, 타일 깨짐)" className="w-full p-4 border rounded-xl h-24 focus:ring-2 focus:ring-brand-500 outline-none resize-none text-sm" />
          </div>

          {matchingStandard && (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-lg text-xs">
              <p className="font-bold text-yellow-800 mb-1">⚖️ 법적 기준: {matchingStandard.title}</p>
              <div className="text-gray-600 line-clamp-3">{matchingStandard.content}</div>
            </div>
          )}
          <button onClick={handleSaveDefect} className="w-full py-4 bg-brand-600 text-white font-bold rounded-xl shadow-md">저장하기</button>
        </div>
        <AnimatePresence>
          {viewerState.isOpen && <PhotoViewer photos={viewerState.photos} initialIndex={viewerState.index} onClose={() => setViewerState(p => ({...p, isOpen: false}))} />}
        </AnimatePresence>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto pb-32 h-full flex flex-col">
      <div className="mb-4">
        <div className="flex items-center justify-between mb-2 px-1">
          <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2"><LayoutGrid size={20} className="text-brand-600" /> 구역 선택</h2>
          <div className="flex gap-1">
