            <button onClick={() => setIsReordering(true)} className={`text-[10px] font-bold px-2 py-1 rounded border flex items-center gap-1 transition-all ${isReordering ? 'bg-brand-600 text-white border-brand-600 shadow-sm' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>
               <ArrowLeftRight size={12}/>
               순서
            </button>
            <button onClick={() => setIsAddingLocation(true)} className="text-[10px] text-brand-600 font-bold px-2 py-1 bg-brand-50 rounded border border-brand-100">+ 추가</button>
          </div>
        </div>

        {isAddingLocation && (
          <div className="mb-3 flex gap-2 p-2 bg-white rounded-lg border animate-in slide-in-from-top-2">
            <input autoFocus type="text" value={newLocationName} onChange={e => setNewLocationName(e.target.value)} placeholder="추가할 구역명" className="flex-1 px-3 py-2 border rounded-lg text-sm outline-none" />
            <button onClick={handleAddLocation} className="bg-brand-600 text-white px-4 py-2 rounded-lg text-sm font-bold">확인</button>
