import React, { useState, useEffect, useRef } from 'react';
import JSZip from 'jszip';
import InfoForm from './components/InfoForm';
import CaptureScreen from './components/CaptureScreen';
import ArchiveScreen from './components/ArchiveScreen';
import LoginScreen from './components/LoginScreen';
import SnapshotModal from './components/SnapshotModal';
import { AppState, InspectionInfo, DefectItem, Snapshot } from './types';
import { generatePDF, getMatchingStandard } from './services/pdfService';
import { 
  loadStep, loadInfo, loadDefects, loadLocations, 
  saveStep, saveInfo, saveDefects, saveLocations, clearAllData, saveToArchive, checkAuth, clearAuth, updateAuthTimestamp,
  saveSnapshot
} from './services/storage';
import { ArrowLeft, FileText, Download, MapPin, Loader2, Archive, Copy, CheckCircle, RotateCcw, Wifi, WifiOff, LogOut, History, Image as ImageIcon } from 'lucide-react';
import { AnimatePresence } from 'framer-motion';
import PhotoViewer from './components/PhotoViewer';

const getLocalISOString = () => {
  const now = new Date();
  const offsetMs = now.getTimezoneOffset() * 60 * 1000;
  // Round to nearest 10 minutes
  const coeff = 1000 * 60 * 10;
  const rounded = new Date(Math.round(now.getTime() / coeff) * coeff);
  const localISOTime = (new Date(rounded.getTime() - offsetMs)).toISOString().slice(0, 16);
  return localISOTime;
};

const INITIAL_INFO: InspectionInfo = {
  apartmentName: '',
  unit: '',
  typeSize: '',
  inspectorName: '',
  phoneNumber: '',
  date: getLocalISOString()
};

// Default categories for 84sqm apartment
const DEFAULT_LOCATIONS = [
  '현관', '현관창고', '공용욕실', '침실3', '침실2', '복도', 
  '펜트리', '거실', '주방', '다용도실', '침실1', '발코니', 
  '실외기실', '대피공간', '드레스룸', '부부욕실'
];

const App: React.FC = () => {
  const [isLoading, setIsLoading] = useState(true);
  const [isAuthorized, setIsAuthorized] = useState(false); // Auth State

  const [step, setStep] = useState<AppState['step']>('info');
  // Track the previous step to allow returning from Archive
  const [lastStep, setLastStep] = useState<AppState['step']>('info');

  const [info, setInfo] = useState<InspectionInfo>(INITIAL_INFO);
  const [defects, setDefects] = useState<DefectItem[]>([]);
  const [locations, setLocations] = useState<string[]>(DEFAULT_LOCATIONS);
  const [isGenerating, setIsGenerating] = useState(false);
  const [isZipping, setIsZipping] = useState(false); // ZIP generation state
  const [showFinishModal, setShowFinishModal] = useState(false);
  const [showSnapshotModal, setShowSnapshotModal] = useState(false);

  // Network Status State
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Photo Viewer State for Preview
  const [viewerState, setViewerState] = useState<{
    isOpen: boolean;
    photos: string[];
    index: number;
  }>({ isOpen: false, photos: [], index: 0 });

  // Use a ref to track if initial load is done
  const isLoadedRef = useRef(false);

  // --- REFS FOR AUTO-SAVE (To access latest state inside interval without resetting it) ---
  const infoRef = useRef(info);
  const defectsRef = useRef(defects);
  const locationsRef = useRef(locations);
  const stepRef = useRef(step);

  // Sync Refs
  useEffect(() => { infoRef.current = info; }, [info]);
  useEffect(() => { defectsRef.current = defects; }, [defects]);
  useEffect(() => { locationsRef.current = locations; }, [locations]);
  useEffect(() => { stepRef.current = step; }, [step]);

  // Initialize app: Load data from IndexedDB
  useEffect(() => {
    const initApp = async () => {
      try {
        // 1. Check Auth (Validation only)
        const hasAuth = checkAuth();
        setIsAuthorized(hasAuth);

        // 2. Load Data (Always load, even if auth fails, so data is ready upon relogin)
        const [savedStep, savedInfo, savedDefects, savedLocations] = await Promise.all([
          loadStep(),
          loadInfo(),
          loadDefects(),
          loadLocations()
        ]);

        if (savedStep) setStep(savedStep);
        if (savedInfo) setInfo(savedInfo);
        if (savedDefects) setDefects(savedDefects);
        if (savedLocations) setLocations(savedLocations);

      } catch (error) {
        console.error("Failed to load saved data", error);
      } finally {
        setIsLoading(false);
        isLoadedRef.current = true;
      }
    };

    initApp();
  }, []);

  // Monitor App Visibility (Background/Foreground)
  useEffect(() => {
    const handleVisibilityChange = () => {
      // When app comes back to foreground
      if (document.visibilityState === 'visible') {
        const isValid = checkAuth();
        // If timed out or session lost, force logout
        if (!isValid) {
          setIsAuthorized(false);
        } else {
          // If valid, just ensure state matches
          setIsAuthorized(true);
        }
      }
    };

    document.addEventListener('visibilitychange', handleVisibilityChange);
    return () => document.removeEventListener('visibilitychange', handleVisibilityChange);
  }, []);

  // Monitor User Activity to Refresh Session (Prevent timeout while working)
  useEffect(() => {
    if (!isAuthorized) return;

    const handleUserActivity = () => {
      // 1. Check if the session has ALREADY expired based on the last timestamp
      const isValid = checkAuth(); 
      if (!isValid) {
        // Expired: Log out immediately, do not update timestamp
        setIsAuthorized(false);
        clearAuth(); 
        alert("장시간 활동이 없어 보안을 위해 잠금 화면으로 이동합니다.\n작업 내용은 안전하게 저장되어 있습니다.");
      } else {
        // Valid: Extend the session
        updateAuthTimestamp();
      }
    };

    // Periodically check for timeout even without interaction (e.g. looking at screen for 1h 1m)
    const idleCheckInterval = setInterval(() => {
       const isValid = checkAuth();
       if (!isValid) {
          setIsAuthorized(false);
          clearAuth();
          // No alert here to prevent modal stacking if user is away, just switch screen
       }
    }, 60 * 1000); // Check every minute

    // Listen to common interaction events
    window.addEventListener('click', handleUserActivity);
    window.addEventListener('touchstart', handleUserActivity);
    window.addEventListener('keydown', handleUserActivity);

    return () => {
      window.removeEventListener('click', handleUserActivity);
      window.removeEventListener('touchstart', handleUserActivity);
      window.removeEventListener('keydown', handleUserActivity);
      clearInterval(idleCheckInterval);
    };
  }, [isAuthorized]);

  // Monitor Network Status
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);

    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);

    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // --- AUTO-SAVE SNAPSHOT LOGIC (FIXED) ---
  useEffect(() => {
    // This effect runs ONCE on mount (and when authorized), ensuring the timer is stable.
    if (!isAuthorized) return;

    console.log("Auto-save timer started: 10 minutes");

    const snapshotInterval = setInterval(() => {
        // Check conditions using Refs (current values)
        // We only save if:
        // 1. Data has finished loading
        // 2. We are in the 'capture' step (actively working)
        // 3. There is at least one defect to save
        if (
            isLoadedRef.current && 
            stepRef.current === 'capture' && 
            defectsRef.current.length > 0
        ) {
            console.log("Executing auto-save...");
            saveSnapshot(infoRef.current, defectsRef.current, locationsRef.current)
                .then(() => console.log("Auto-save success"))
                .catch(err => console.error("Auto-save failed", err));
        }
    }, 10 * 60 * 1000); // Exactly 10 minutes

    return () => clearInterval(snapshotInterval);
  }, [isAuthorized]); // Only restart if auth status changes, NOT when data changes
  // -------------------------------

  // Prevent accidental back navigation
  useEffect(() => {
    // Push current state to history to create a buffer
    history.pushState(null, '', window.location.href);

    const handlePopState = () => {
      // When back button is pressed, push state again to stay on page
      history.pushState(null, '', window.location.href);
    };

    window.addEventListener('popstate', handlePopState);
    return () => {
      window.removeEventListener('popstate', handlePopState);
    };
  }, []);

  // Persist state changes
  useEffect(() => {
    if (isLoadedRef.current) saveStep(step);
  }, [step]);

  useEffect(() => {
    if (isLoadedRef.current) saveInfo(info);
  }, [info]);

  useEffect(() => {
    if (isLoadedRef.current) saveDefects(defects);
  }, [defects]);

  useEffect(() => {
    if (isLoadedRef.current) saveLocations(locations);
  }, [locations]);

  const handleInfoSubmit = (data: InspectionInfo) => {
    setInfo(data);
    setStep('capture');
  };

  const handleGenerateReport = async () => {
    setIsGenerating(true);
    setTimeout(async () => {
      await generatePDF(info, defects);
      setIsGenerating(false);
    }, 100);
  };

  const handleDownloadPhotos = async () => {
    if (defects.length === 0) {
      alert("다운로드할 사진이 없습니다.");
      return;
    }

    setIsZipping(true);
    try {
      const zip = new JSZip();

      // Sanitize folder name
      const safeUnit = info.unit.replace(/[\/\\]/g, '_').trim();
      const rootFolderName = `${info.apartmentName}_${safeUnit}_현장사진`;
      const rootFolder = zip.folder(rootFolderName);

      if (!rootFolder) throw new Error("ZIP 폴더 생성 실패");

      // Group by location
      const grouped = defects.reduce((acc, d) => {
        (acc[d.location] = acc[d.location] || []).push(d);
        return acc;
      }, {} as Record<string, DefectItem[]>);

      const promises: Promise<void>[] = [];

      Object.entries(grouped).forEach(([loc, locDefects]) => {
        const defectsList = locDefects as DefectItem[];
        const locFolder = rootFolder.folder(loc);
        if (!locFolder) return;

        defectsList.forEach((d, i) => {
           // Index: i+1
           // Sanitize description for filename (max 15 chars)
           const safeDesc = d.description.replace(/[^a-zA-Z0-9가-힣\s]/g, '').trim().substring(0, 15) || '하자';

           // Far Photos
           d.farPhotos.forEach((url, pIdx) => {
             promises.push(
                fetch(url).then(r => r.blob()).then(blob => {
                   locFolder.file(`${i+1}_${safeDesc}_원거리_${pIdx+1}.jpg`, blob);
                })
             );
           });

           // Near Photos
           d.nearPhotos.forEach((url, pIdx) => {
             promises.push(
                fetch(url).then(r => r.blob()).then(blob => {
                   locFolder.file(`${i+1}_${safeDesc}_근거리_${pIdx+1}.jpg`, blob);
                })
             );
           });
        });
      });

      await Promise.all(promises);

      const content = await zip.generateAsync({ type: "blob" });
      const url = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = url;
      link.download = `${info.apartmentName}_${safeUnit}_현장사진.zip`;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      setTimeout(() => URL.revokeObjectURL(url), 1000);

    } catch (e) {
      console.error("ZIP Error", e);
      alert("사진 다운로드 중 오류가 발생했습니다.");
    } finally {
      setIsZipping(false);
    }
  };

  const handleCopyText = () => {
    if (defects.length === 0) {
      alert('복사할 하자 내역이 없습니다.');
      return;
    }

    const dateStr = new Date(info.date).toLocaleString('ko-KR');

    let text = `[사전점검 리포트 - Double Check]\n\n`;
    text += `■ 현장 정보\n`;
    text += `- 현장명: ${info.apartmentName}\n`;
    text += `- 동/호수: ${info.unit}\n`;
    text += `- 타입: ${info.typeSize}\n`;
    text += `- 고객명: ${info.inspectorName} (${info.phoneNumber})\n`;
    text += `- 점검일: ${dateStr}\n`;
    text += `\n================================\n\n`;
    text += `■ 하자 세부 내역 (총 ${defects.length}건)\n\n`;

    // 1. Group by location
    const grouped = defects.reduce((acc, d) => {
      (acc[d.location] = acc[d.location] || []).push(d);
      return acc;
    }, {} as Record<string, DefectItem[]>);

    // 2. Get ALL defect locations (not just the ones in 'locations' array)
    const defectLocations = Object.keys(grouped);

    // 3. Sort logic:
    // - If location is in the known 'locations' list, sort by that order
    // - If not, put it at the end
    defectLocations.sort((a, b) => {
      const idxA = locations.indexOf(a);
      const idxB = locations.indexOf(b);

      // Both in list: respect list order
      if (idxA !== -1 && idxB !== -1) return idxA - idxB;
      // One in list: prioritized
      if (idxA !== -1) return -1;
      if (idxB !== -1) return 1;
      // Neither: alphabetical
      return a.localeCompare(b);
    });

    defectLocations.forEach(loc => {
      text += `[${loc}]\n`;
      const locDefects = grouped[loc] as DefectItem[];
      locDefects.forEach((d, i) => {
        text += `${i + 1}. ${d.description}\n`;
      });
      text += '\n';
    });

    navigator.clipboard.writeText(text).then(() => {
      alert('고객 정보와 하자 내역이 모두 복사되었습니다.');
    }).catch(err => {
      console.error('Failed to copy: ', err);
      alert('텍스트 복사에 실패했습니다.');
    });
  };

  const handleCompleteClick = () => {
    setShowFinishModal(true);
  };

  const confirmCompleteAndArchive = async () => {
    setShowFinishModal(false);
    setIsLoading(true);

    try {
      // 1. Archive current data
      await saveToArchive(info, defects, locations);

      // 2. Clear active data
      await clearAllData();
      localStorage.removeItem('info_form_draft');

      // 3. Reset State
      setInfo({ ...INITIAL_INFO, date: getLocalISOString() });
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setStep('info');

      alert('저장이 완료되었습니다. 보관함에서 언제든지 내역을 확인하고 수정할 수 있습니다.');
    } catch (e) {
      console.error(e);
      alert('저장 중 오류가 발생했습니다. 잠시 후 다시 시도해주세요.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleReset = async () => {
    if (confirm('모든 데이터가 초기화됩니다 (보관되지 않음). 처음으로 돌아가시겠습니까?')) {
      setIsLoading(true);
      await clearAllData();
      setStep('info');
      setDefects([]);
      setLocations(DEFAULT_LOCATIONS);
      setInfo(INITIAL_INFO);
      localStorage.removeItem('info_form_draft'); 
      isLoadedRef.current = true;
      setIsLoading(false);
    }
  };

  const handleLogout = () => {
    if (confirm('보안을 위해 앱을 잠그시겠습니까?')) {
      clearAuth();
      setIsAuthorized(false);
    }
  };

  const handleLoadArchive = (archivedInfo: InspectionInfo, archivedDefects: DefectItem[], archivedLocations: string[]) => {
    setInfo(archivedInfo);
    setDefects(archivedDefects);
    setLocations(archivedLocations);
    setStep('preview'); // Go straight to preview to check/download
  };

  const handleRestoreSnapshot = (snapshot: Snapshot) => {
     setInfo(snapshot.info);
     setDefects(snapshot.defects);
     setLocations(snapshot.locations);
     setShowSnapshotModal(false);
     setStep('capture'); // Go to capture screen to continue work
  };

  const openPhotoViewer = (photos: string[], index: number) => {
    setViewerState({
      isOpen: true,
      photos,
      index
    });
  };

  // Group defects by location for preview
  const groupedDefects = defects.reduce((acc, defect) => {
    (acc[defect.location] = acc[defect.location] || []).push(defect);
    return acc;
  }, {} as Record<string, DefectItem[]>);

  // FIX: Also ensure preview uses all defect locations, sorted by preference
  const activeLocationsInPreview = Object.keys(groupedDefects).sort((a, b) => {
      const idxA = locations.indexOf(a);
      const idxB = locations.indexOf(b);
      if (idxA !== -1 && idxB !== -1) return idxA - idxB;
      if (idxA !== -1) return -1;
      if (idxB !== -1) return 1;
      return a.localeCompare(b);
  });

  if (isLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-gray-50 text-gray-500">
        <Loader2 size={40} className="animate-spin text-brand-600 mb-4" />
        <p>데이터 처리 중...</p>
      </div>
    );
  }

  // SHOW LOGIN SCREEN IF NOT AUTHORIZED
  if (!isAuthorized) {
    return <LoginScreen onSuccess={() => setIsAuthorized(true)} />;
  }

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col pt-safe relative">
      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-20">
        {/* Offline Banner */}
        {!isOnline && (
          <div className="bg-gray-800 text-white text-xs py-2 px-4 text-center flex items-center justify-center gap-2 animate-in slide-in-from-top">
            <WifiOff size={14} className="text-red-400" />
            <span>오프라인 모드: 인터넷이 없어도 작성 내용은 기기에 안전하게 저장됩니다.</span>
          </div>
        )}

        <div className="px-4 py-3 max-w-md mx-auto flex items-center justify-between">
          <div className="flex items-center gap-3">
            {step !== 'info' && step !== 'archive' && (
              <button 
                onClick={() => setStep(step === 'preview' ? 'capture' : 'info')}
                className="p-2 -ml-2 rounded-full hover:bg-gray-100 text-gray-600"
              >
                <ArrowLeft size={20} />
              </button>
            )}
            <h1 className="font-bold text-gray-800 text-lg flex items-center gap-2">
              <FileText className="text-brand-600" size={24} />
              Double Check
            </h1>
          </div>
          <div className="flex items-center gap-2">
            {step === 'capture' && defects.length > 0 && (
               <button onClick={handleReset} className="text-xs text-red-500 font-medium px-2 py-1 rounded hover:bg-red-50">
                 초기화
               </button>
            )}
            {step === 'info' && (
               <button onClick={handleLogout} className="text-gray-400 p-2 hover:bg-gray-100 rounded-full" title="잠금(로그아웃)">
                 <LogOut size={20}/>
               </button>
            )}
            {step !== 'archive' && (
              <>
                <button 
                    onClick={() => setShowSnapshotModal(true)}
                    className="text-gray-600 p-2 hover:bg-gray-100 rounded-full"
                    title="임시 보관함 (자동저장)"
                >
                    <History size={22} />
                </button>
                <button 
                    onClick={() => {
                    setLastStep(step);
                    setStep('archive');
                    }}
                    className="text-gray-600 p-2 hover:bg-gray-100 rounded-full"
                    title="보관함"
                >
                    <Archive size={22} />
                </button>
              </>
            )}
          </div>
        </div>
      </header>

      {/* Content */}
      <main className="flex-1 p-4 max-w-md mx-auto w-full">
        {step === 'info' && (
          <InfoForm initialData={info} onSubmit={handleInfoSubmit} />
        )}

        {step === 'capture' && (
          <CaptureScreen 
            defects={defects} 
            setDefects={setDefects}
            locations={locations}
            setLocations={setLocations}
            onFinish={() => setStep('preview')} 
          />
        )}

        {step === 'archive' && (
          <ArchiveScreen 
            onLoad={handleLoadArchive}
            onGoBack={() => setStep(lastStep)}
            onGoHome={() => setStep('info')}
          />
        )}

        {step === 'preview' && (
          <div className="bg-white rounded-2xl shadow-sm border border-gray-100 overflow-hidden pb-44">
            <div className="p-6 border-b border-gray-100 flex justify-between items-center">
              <div>
                <h2 className="text-xl font-bold text-gray-800 mb-1">보고서 미리보기</h2>
                <p className="text-sm text-gray-500">내용을 확인하고 저장하세요.</p>
              </div>
              <button
                onClick={handleCopyText}
                className="text-brand-600 bg-brand-50 hover:bg-brand-100 px-3 py-1.5 rounded-lg text-sm font-bold flex items-center gap-1 transition"
              >
                <Copy size={14} />
                텍스트 복사
              </button>
            </div>

            <div className="p-6 bg-gray-50 text-sm space-y-4">
              <div className="bg-white p-4 rounded-lg border border-gray-200">
                <h3 className="font-bold text-gray-800 mb-3 border-b pb-2">기본 정보</h3>
                <div className="grid grid-cols-2 gap-y-2 gap-x-4">
                  <span className="text-gray-500">현장명</span> <span className="font-medium text-right">{info.apartmentName}</span>
                  <span className="text-gray-500">동/호수</span> <span className="font-medium text-right">{info.unit}</span>
                  <span className="text-gray-500">타입</span> <span className="font-medium text-right">{info.typeSize}</span>
                  <span className="text-gray-500">고객명</span> <span className="font-medium text-right">{info.inspectorName}</span>
                  <span className="text-gray-500">일시</span> <span className="font-medium text-right">{new Date(info.date).toLocaleString('ko-KR')}</span>
                </div>
              </div>

              <div className="space-y-6">
                <h3 className="font-bold text-gray-800 ml-1 text-lg">하자 내역 (총 {defects.length}건)</h3>

                {activeLocationsInPreview.length === 0 ? (
                  <p className="text-center text-gray-400 py-4">등록된 하자가 없습니다.</p>
                ) : (
                  activeLocationsInPreview.map((loc) => (
                    <div key={loc} className="space-y-3">
                      <div className="flex items-center gap-2 border-b border-gray-200 pb-1">
                        <MapPin size={16} className="text-brand-600" />
                        <h4 className="font-bold text-gray-800 text-base">{loc}</h4>
                        <span className="text-xs bg-gray-100 text-gray-600 px-2 py-0.5 rounded-full">{groupedDefects[loc].length}건</span>
                      </div>

                      {groupedDefects[loc].map((d, i) => {
                        const standard = getMatchingStandard(d.description);
                        const allPhotos = [...d.farPhotos, ...d.nearPhotos];

                        return (
                          <div key={d.id} className="bg-white p-4 rounded-xl border border-gray-200 shadow-sm">
                            <div className="flex items-center gap-2 mb-3">
                              <span 
                                className="flex-shrink-0 w-6 h-6 text-white rounded-full flex items-center justify-center text-xs font-bold"
                                style={{ backgroundColor: 'rgb(0, 15, 85)' }}
                              >
                                {i + 1}
                              </span>
                              <p className="font-bold text-gray-800 line-clamp-1 flex-1">{d.description}</p>
                            </div>

                            <div className="grid grid-cols-5 gap-1 mb-3">
                              {d.farPhotos.map((p, idx) => (
                                <div key={`far-${idx}`} className="aspect-square bg-gray-100 rounded overflow-hidden relative border border-green-200 cursor-zoom-in" onClick={() => openPhotoViewer(allPhotos, idx)}>
                                  <img src={p} className="w-full h-full object-cover" />
                                  <div className="absolute bottom-0 left-0 right-0 bg-green-500/80 h-1.5"></div>
                                </div>
                              ))}
                              {d.nearPhotos.map((p, idx) => (
                                <div key={`near-${idx}`} className="aspect-square bg-gray-100 rounded overflow-hidden relative border border-blue-200 cursor-zoom-in" onClick={() => openPhotoViewer(allPhotos, d.farPhotos.length + idx)}>
                                  <img src={p} className="w-full h-full object-cover" />
                                  <div className="absolute bottom-0 left-0 right-0 bg-blue-500/80 h-1.5"></div>
                                </div>
                              ))}
                            </div>

                            {standard && (
                              <div className="bg-yellow-50 border border-yellow-200 rounded-lg p-3 text-xs">
                                <h5 className="font-bold text-yellow-800 flex items-center gap-2 mb-1">
                                  <span className="bg-yellow-600 text-white text-[10px] px-1.5 py-0.5 rounded">관련 기준</span>
                                  {standard.title}
                                </h5>
                                <p className="text-gray-700 whitespace-pre-wrap leading-relaxed">{standard.content}</p>
                              </div>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  ))
                )}
              </div>
            </div>

            <div className="fixed bottom-0 left-0 right-0 p-4 pb-safe bg-white/90 backdrop-blur-md border-t border-gray-200 z-10 space-y-2">
              <div className="flex gap-2 w-full max-w-md mx-auto">
                  <button
                    onClick={handleGenerateReport}
                    disabled={isGenerating || isZipping}
                    className="flex-[2] bg-brand-600 hover:bg-brand-700 text-white font-bold py-3.5 px-6 rounded-xl shadow-lg flex items-center justify-center gap-2 transition disabled:opacity-70 disabled:cursor-wait"
                  >
                    {isGenerating ? (
                      <>
                        <Loader2 className="animate-spin" size={20} />
                        PDF 생성 중...
                      </>
                    ) : (
                      <>
                        <Download size={20} />
                        PDF 다운로드
                      </>
                    )}
                  </button>

                  <button
                    onClick={handleDownloadPhotos}
                    disabled={isGenerating || isZipping}
                    className="flex-1 bg-gray-700 hover:bg-gray-800 text-white font-bold py-3.5 px-2 rounded-xl shadow-lg flex items-center justify-center gap-2 transition disabled:opacity-70 disabled:cursor-wait"
                  >
                      {isZipping ? (
                        <Loader2 className="animate-spin" size={18} />
                      ) : (
                        <ImageIcon size={18} />
                      )}
                      <span className="text-sm">사진 전체</span>
                  </button>
              </div>

              <div className="grid grid-cols-2 gap-2 max-w-md mx-auto">
                 <button
                  onClick={handleCompleteClick}
                  className="bg-gray-800 hover:bg-gray-900 text-white font-bold py-3 px-4 rounded-xl flex items-center justify-center gap-2 transition"
                >
                  <CheckCircle size={18} />
                  점검 완료 및 보관
                </button>
                <button
                  onClick={() => setStep('capture')}
                  className="bg-white border border-gray-300 text-gray-700 font-bold py-3 px-4 rounded-xl hover:bg-gray-50 transition flex items-center justify-center gap-2"
                >
                  <RotateCcw size={18} />
                  수정하기
                </button>
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Fullscreen Photo Viewer for Preview Mode */}
      <AnimatePresence>
        {viewerState.isOpen && (
          <PhotoViewer 
            photos={viewerState.photos}
            initialIndex={viewerState.index}
            onClose={() => setViewerState(prev => ({ ...prev, isOpen: false }))}
          />
        )}
      </AnimatePresence>

      {/* Snapshot Modal (Temp Archive) */}
      {showSnapshotModal && (
        <SnapshotModal 
            onClose={() => setShowSnapshotModal(false)} 
            onRestore={handleRestoreSnapshot}
        />
      )}

      {/* Confirmation Modal */}
      {showFinishModal && (
        <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 animate-in fade-in duration-200">
          <div className="bg-white rounded-2xl w-full max-w-sm p-6 shadow-xl relative overflow-hidden">
            <div className="absolute top-0 left-0 w-full h-1 bg-brand-500"></div>

            <div className="flex items-start gap-4 mb-4">
              <div className="bg-brand-100 p-3 rounded-full text-brand-600 flex-shrink-0">
                <CheckCircle size={28} />
              </div>
              <div>
                <h3 className="text-lg font-bold text-gray-900">점검을 완료하시겠습니까?</h3>
                <p className="text-sm text-gray-500 mt-1 leading-relaxed">
                  작성하신 점검 자료를 보관함에 안전하게 저장하고 초기 화면으로 돌아갑니다.
                </p>
              </div>
            </div>

            <div className="bg-gray-50 rounded-xl p-3 mb-6 text-xs text-gray-600 border border-gray-100">
               <ul className="space-y-1 list-disc list-inside">
                 <li>저장된 자료는 <b>보관함</b>에서 다시 불러올 수 있습니다.</li>
                 <li>아직 작성이 끝나지 않았다면 <b>취소</b>를 눌러주세요.</li>
               </ul>
            </div>

            <div className="flex flex-col gap-3">
              <button 
                onClick={confirmCompleteAndArchive}
                className="w-full py-3.5 bg-brand-600 hover:bg-brand-700 text-white font-bold rounded-xl flex items-center justify-center gap-2 transition shadow-sm"
              >
                네, 점검을 완료했습니다
                <span className="text-[10px] font-normal bg-brand-700/50 px-1.5 py-0.5 rounded ml-1">저장 및 종료</span>
              </button>
              <button 
                onClick={() => setShowFinishModal(false)}
                className="w-full py-3.5 bg-white border border-gray-300 text-gray-700 font-bold rounded-xl hover:bg-gray-50 transition"
              >
                아니요, 더 작성할게요
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default App;

import React, { useState, useRef, useEffect } from 'react';
import { DefectItem, InspectionInfo } from '../types';
import { Camera, Trash2, Save, Plus, MapPin, ZoomIn, X, LayoutGrid, Pencil, RefreshCw, AlertTriangle, ArrowLeftRight, Check, Image as ImageIcon, Users, Share2, Download, Upload, FileText, Send, CheckCircle2, Copy, GripVertical, Loader2 } from 'lucide-react';
import { saveDraft, loadDraft, clearDraft, exportActiveDataToDataFile, mergeActiveDataFromFile, loadInfo } from '../services/storage';
import { getMatchingStandard, generatePDFBlob } from '../services/pdfService';
import { motion, AnimatePresence, useDragControls, PanInfo } from 'framer-motion';
import PhotoViewer from './PhotoViewer';

interface CaptureScreenProps {
  defects: DefectItem[];
  setDefects: React.Dispatch<React.SetStateAction<DefectItem[]>>;
  locations: string[];
  setLocations: React.Dispatch<React.SetStateAction<string[]>>;
  onFinish: () => void;
}

const MIN_FAR = 1;
const MAX_FAR = 3;
const MIN_NEAR = 1;
const MAX_NEAR = 10;

// --- Image Compression Utility (Legacy Mode for Maximum Stability on iOS) ---
const compressImage = async (file: File): Promise<Blob> => {
  // Conservative settings for iOS stability
  const MAX_WIDTH = 800; 
  const MAX_HEIGHT = 800;
  const QUALITY = 0.6; 

  return new Promise((resolve, reject) => {
    const img = new Image();
    // Create a temporary URL just for processing
    const url = URL.createObjectURL(file);

    img.onload = () => {
      // 1. Calculate new size
      let width = img.width;
      let height = img.height;

      if (width > height) {
        if (width > MAX_WIDTH) {
          height = Math.round(height * (MAX_WIDTH / width));
          width = MAX_WIDTH;
        }
      } else {
        if (height > MAX_HEIGHT) {
          width = Math.round(width * (MAX_HEIGHT / height));
          height = MAX_HEIGHT;
        }
      }

      // 2. Create Canvas
      const canvas = document.createElement('canvas');
      canvas.width = width;
      canvas.height = height;
      const ctx = canvas.getContext('2d');

      if (ctx) {
        // 3. Draw Image
        ctx.drawImage(img, 0, 0, width, height);

        // 4. Export Blob
        canvas.toBlob((blob) => {
          // Cleanup
          URL.revokeObjectURL(url);
          img.src = ''; 
          canvas.width = 0; 
          canvas.height = 0;

          if (blob) resolve(blob);
          else reject(new Error("Compression failed"));
        }, 'image/jpeg', QUALITY);
      } else {
        URL.revokeObjectURL(url);
        reject(new Error("Canvas context missing"));
      }
    };

    img.onerror = (err) => {
      URL.revokeObjectURL(url);
      console.error("Image load error", err);
      reject(new Error("이미지를 읽을 수 없습니다."));
    };

    img.src = url;
  });
};

// --- Auto Save/Download Utility ---
const saveToDevice = (file: File | Blob, prefix: string) => {
  try {
    const url = URL.createObjectURL(file);
    const a = document.createElement('a');
    a.href = url;
    const now = new Date();
    const timestamp = now.toISOString().replace(/[-:T.]/g, '').slice(2, 14);
    const millis = String(now.getMilliseconds()).padStart(3, '0');

    a.download = `DC_${prefix}_${timestamp}_${millis}.jpg`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);

    // Revoke specifically for this download URL after a delay
    setTimeout(() => URL.revokeObjectURL(url), 1000); 
  } catch (e) {
    console.error("Auto-save failed", e);
  }
};

// Custom Sortable Item for Grid Layout
const SortableItem: React.FC<{ 
  loc: string, 
  active: boolean, 
  draggingLoc: string | null,
  onDragStart: (loc: string) => void,
  onDragEnd: () => void,
  onDragTrigger: (e: any, info: PanInfo, loc: string) => void
}> = ({ loc, active, draggingLoc, onDragStart, onDragEnd, onDragTrigger }) => {
  const controls = useDragControls();

  return (
    <motion.div
      layout
      data-loc={loc}
      initial={false}
      animate={{
        scale: draggingLoc === loc ? 1.08 : 1,
        zIndex: draggingLoc === loc ? 100 : 0,
        boxShadow: draggingLoc === loc ? "0px 10px 20px rgba(0,0,0,0.2)" : "0px 1px 2px rgba(0,0,0,0.05)"
      }}
      drag
      dragControls={controls}
      dragListener={false} // Only handle triggers drag
      dragElastic={0.1}
      dragMomentum={false}
      onDragStart={() => onDragStart(loc)}
      onDragEnd={onDragEnd}
      onDrag={(e, info) => onDragTrigger(e, info, loc)}
      className={`
        bg-white rounded-xl border shadow-sm flex flex-col items-center justify-center 
        select-none h-20 p-2 relative overflow-hidden transition-colors
        ${active ? 'border-brand-500 ring-2 ring-brand-500 bg-brand-50' : 'border-gray-200 hover:border-brand-300'}
      `}
    >
      <div className="flex-1 flex flex-col items-center justify-center w-full min-w-0">
        <div className={`p-1.5 rounded-full mb-1 ${active ? 'bg-brand-100 text-brand-600' : 'bg-gray-100 text-gray-500'}`}>
           <MapPin size={16}/>
        </div>
        <span className={`font-bold truncate text-xs w-full text-center ${active ? 'text-brand-800' : 'text-gray-700'}`}>{loc}</span>
      </div>

      {/* Drag Handle */}
      <div 
        className="absolute top-0 right-0 p-2 cursor-grab active:cursor-grabbing text-gray-300 hover:text-gray-500 touch-none"
        onPointerDown={(e) => controls.start(e)}
      >
        <GripVertical size={16} />
      </div>
    </motion.div>
  );
};

const CaptureScreen: React.FC<CaptureScreenProps> = ({ 
  defects, 
  setDefects, 
  locations,
  setLocations,
  onFinish 
}) => {
  const [activeLocation, setActiveLocation] = useState<string>(locations[0]);
  const [isCreating, setIsCreating] = useState(false);
  const [isAddingLocation, setIsAddingLocation] = useState(false);
  const [isReordering, setIsReordering] = useState(false);
  const [newLocationName, setNewLocationName] = useState('');

  const [showTeamModal, setShowTeamModal] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [processingMsg, setProcessingMsg] = useState('');
  const [isCompressing, setIsCompressing] = useState(false); // Image processing state

  const [preparedFile, setPreparedFile] = useState<{file: File, type: 'JSON' | 'PDF'} | null>(null);

  const [editingId, setEditingId] = useState<string | null>(null);
  const [tempFarPhotos, setTempFarPhotos] = useState<string[]>([]);
  const [tempNearPhotos, setTempNearPhotos] = useState<string[]>([]);
  const [description, setDescription] = useState('');

  const cameraInputFarRef = useRef<HTMLInputElement>(null);
  const galleryInputFarRef = useRef<HTMLInputElement>(null);
  const cameraInputNearRef = useRef<HTMLInputElement>(null);
  const galleryInputNearRef = useRef<HTMLInputElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Dragging State
  const [draggingLoc, setDraggingLoc] = useState<string | null>(null);

  const [viewerState, setViewerState] = useState<{
    isOpen: boolean;
    photos: string[];
    index: number;
  }>({ isOpen: false, photos: [], index: 0 });

  const currentLocationDefects = defects.filter(d => d.location === activeLocation);

  useEffect(() => {
    const restoreDraft = async () => {
      try {
        const draft = await loadDraft();
        if (draft) {
          if (!locations.includes(draft.location)) {
            setLocations(prev => [...prev, draft.location]);
          }
          setActiveLocation(draft.location);
          setTempFarPhotos(draft.farPhotos);
          setTempNearPhotos(draft.nearPhotos);
          setDescription(draft.description);
          setEditingId(draft.editingId);
          setIsCreating(true);
        }
      } catch (e) {
        console.error("Failed to restore draft", e);
      }
    };
    restoreDraft();
  }, []);

  useEffect(() => {
    if (!isCreating) return;
    const timer = setTimeout(() => {
      if (!editingId && tempFarPhotos.length === 0 && tempNearPhotos.length === 0 && !description) return;
      saveDraft({
        location: activeLocation,
        farPhotos: tempFarPhotos,
        nearPhotos: tempNearPhotos,
        description,
        editingId
      });
    }, 500);
    return () => clearTimeout(timer);
  }, [isCreating, activeLocation, tempFarPhotos, tempNearPhotos, description, editingId]);

  // Clean up object URLs when component unmounts or photos change to free memory
  useEffect(() => {
     return () => {
         tempFarPhotos.forEach(url => URL.revokeObjectURL(url));
         tempNearPhotos.forEach(url => URL.revokeObjectURL(url));
     };
  }, [tempFarPhotos, tempNearPhotos]);

  const resetForm = async () => {
    await clearDraft();
    setTempFarPhotos([]);
    setTempNearPhotos([]);
    setDescription('');
    setEditingId(null);
    setIsCreating(false);
  };

  const handleStartCreation = () => {
    setTempFarPhotos([]);
    setTempNearPhotos([]);
    setDescription('');
    setEditingId(null);
    setIsCreating(true);
  };

  const handleStartEdit = (defect: DefectItem) => {
    setTempFarPhotos([...defect.farPhotos]);
    setTempNearPhotos([...defect.nearPhotos]);
    setDescription(defect.description);
    setEditingId(defect.id);
    setIsCreating(true);
  };

  const handleAddLocation = () => {
    if (newLocationName.trim() && !locations.includes(newLocationName.trim())) {
      const newLoc = newLocationName.trim();
      setLocations([...locations, newLoc]);
      setActiveLocation(newLoc);
      setNewLocationName('');
      setIsAddingLocation(false);
    } else {
      alert('유효한 구역명을 입력해주세요.');
    }
  };

  const handlePhotoAdd = async (e: React.ChangeEvent<HTMLInputElement>, type: 'FAR' | 'NEAR') => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      // 1. Show loading state FIRST
      setIsCompressing(true);

      // 2. Save Original to Device (Fire & Forget)
      // Do this async so it doesn't block the UI
      setTimeout(() => {
         saveToDevice(file, type === 'FAR' ? 'Far' : 'Near');
      }, 0);

      // 3. Force a small delay to ensure UI updates to "Loading"
      await new Promise(resolve => setTimeout(resolve, 50));

      // 4. Compress the image (Heavy CPU task)
      const compressedBlob = await compressImage(file);
      const compressedUrl = URL.createObjectURL(compressedBlob);

      // 5. Update State with the COMPRESSED URL (Safe for rendering)
      if (type === 'FAR') {
        setTempFarPhotos(prev => [...prev, compressedUrl]);
      } else {
        setTempNearPhotos(prev => [...prev, compressedUrl]);
      }
    } catch (err) {
      console.error("Image processing error", err);
      alert("사진 처리에 실패했습니다. 메모리가 부족할 수 있습니다.");
    } finally {
      setIsCompressing(false);
      // Clear input to allow re-selecting same file
      e.target.value = '';
    }
  };

  const removePhoto = (type: 'FAR' | 'NEAR', index: number) => {
    if (type === 'FAR') {
      const urlToRemove = tempFarPhotos[index];
      setTempFarPhotos(prev => prev.filter((_, i) => i !== index));
      URL.revokeObjectURL(urlToRemove);
    } else {
      const urlToRemove = tempNearPhotos[index];
      setTempNearPhotos(prev => prev.filter((_, i) => i !== index));
      URL.revokeObjectURL(urlToRemove);
    }
  };

  const handleSaveDefect = async () => {
    if (tempFarPhotos.length < MIN_FAR || tempNearPhotos.length < MIN_NEAR || !description.trim()) {
      alert('필수 사진과 내용을 입력해주세요.');
      return;
    }
    if (editingId) {
      setDefects(prev => prev.map(d => d.id === editingId ? { ...d, farPhotos: tempFarPhotos, nearPhotos: tempNearPhotos, description } : d));
    } else {
      setDefects(prev => [...prev, { id: Date.now().toString(), location: activeLocation, farPhotos: tempFarPhotos, nearPhotos: tempNearPhotos, description, timestamp: Date.now() }]);
    }
    await resetForm();
  };

  const handleDeleteDefect = (id: string, e?: React.MouseEvent) => {
    if (e) e.stopPropagation();
    if (window.confirm('삭제하시겠습니까?')) {
      setDefects(prev => prev.filter(d => d.id !== id));
      if (editingId === id) resetForm();
    }
  };

  const handlePrepareData = async () => {
    if (defects.length === 0) {
      alert('공유할 데이터가 없습니다.');
      return;
    }
    setPreparedFile(null);
    setIsProcessing(true);
    setProcessingMsg('데이터 파일 생성 중...');
    try {
      const info = await loadInfo();
      if (!info) throw new Error("Info missing");

      const dataBlob = await exportActiveDataToDataFile(info, defects);
      const fileName = `DoubleCheck_Data_${info.unit}_${new Date().getHours()}시.json`;
      const file = new File([dataBlob], fileName, { type: 'text/plain' });

      setPreparedFile({ file, type: 'JSON' });
    } catch (e) {
      console.error(e);
      alert('데이터 생성 실패: ' + (e as any).message);
    } finally {
      setIsProcessing(false);
    }
  };

  const executeDownload = () => {
    if (!preparedFile) return;
    const url = URL.createObjectURL(preparedFile.file);
    const a = document.createElement('a');
    a.href = url;
    a.download = preparedFile.file.name;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    setTimeout(() => URL.revokeObjectURL(url), 100);

    if (preparedFile.type === 'JSON') {
       alert("파일이 저장되었습니다!\n\n[카카오톡 채팅방] -> [+] -> [파일]을 눌러\n방금 저장된 파일(DoubleCheck_Data...)을 전송하세요.");
    } else {
       alert("PDF 파일이 저장되었습니다.");
    }
  };

  const handleMergeFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    if (!confirm('선택한 파일의 내용을 현재 작성 중인 내용에 합치시겠습니까?')) {
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    setIsProcessing(true);
    setProcessingMsg('데이터 분석 및 병합 중...');

    try {
      const { mergedDefects, newLocations } = await mergeActiveDataFromFile(file);
      setDefects(prev => [...prev, ...mergedDefects]);
      setLocations(prev => {
          const uniqueLocs = new Set([...prev, ...newLocations]);
          return Array.from(uniqueLocs);
      });
      setShowTeamModal(false);
      alert(`성공적으로 합쳐졌습니다!\n- 추가된 하자: ${mergedDefects.length}건`);
    } catch (err: any) {
      console.error(err);
      alert('데이터 가져오기 실패: ' + err.message);
    } finally {
      setIsProcessing(false);
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  // Custom Drag Handler for Grid Sorting
  const handleDrag = (e: any, { point }: PanInfo, loc: string) => {
    // Find the element currently under the pointer
    const elements = Array.from(document.querySelectorAll('[data-loc]'));
    const target = elements.find(el => {
        if (el.getAttribute('data-loc') === loc) return false;
        const rect = el.getBoundingClientRect();
        return point.x >= rect.left && point.x <= rect.right && point.y >= rect.top && point.y <= rect.bottom;
    });

    if (target) {
        const targetLoc = target.getAttribute('data-loc');
        if (targetLoc && targetLoc !== loc) {
            const fromIndex = locations.indexOf(loc);
            const toIndex = locations.indexOf(targetLoc);

            if (fromIndex !== -1 && toIndex !== -1 && fromIndex !== toIndex) {
                 const newLocations = [...locations];
                 const [moved] = newLocations.splice(fromIndex, 1);
                 newLocations.splice(toIndex, 0, moved);
                 setLocations(newLocations);
            }
        }
    }
  };

  const renderLocationItem = (loc: string) => {
    const count = defects.filter(d => d.location === loc).length;
    const isActive = activeLocation === loc;
    return (
      <button key={loc} onClick={() => !isReordering && setActiveLocation(loc)} className={`px-4 py-2 rounded-xl text-sm font-bold transition-all border whitespace-nowrap ${isActive ? 'bg-brand-600 text-white border-brand-600 shadow-md' : 'bg-white text-gray-600 border-gray-200'}`}>
        {loc} {count > 0 && <span className="text-[10px] ml-1 opacity-70">({count})</span>}
      </button>
    );
  };

  if (isCreating) {
    const matchingStandard = getMatchingStandard(description);
    const currentIdx = editingId ? defects.findIndex(d => d.id === editingId) + 1 : currentLocationDefects.length + 1;

    return (
      <div className="bg-white rounded-2xl p-6 shadow-sm border border-gray-100 max-w-md mx-auto relative pb-safe animate-in fade-in zoom-in-95">

        {/* Loading Overlay during Compression - NOW BLOCKING to prevent UI interaction issues */}
        {isCompressing && (
           <div className="absolute inset-0 bg-white/90 z-50 flex flex-col items-center justify-center rounded-2xl backdrop-blur-sm">
              <Loader2 className="animate-spin text-brand-600 mb-2" size={32} />
              <p className="text-xs font-bold text-brand-700">사진 최적화 중...</p>
           </div>
        )}

        <div className="flex justify-between items-center mb-6 border-b pb-4">
          <div className="flex flex-col">
            <h3 className="text-xl font-bold text-gray-800">{editingId ? '내용 수정' : '하자 등록'}</h3>
            <span className="text-xs text-brand-600 font-bold mt-1">[{activeLocation}] 하자 #{currentIdx}</span>
          </div>
          <button onClick={resetForm} className="text-gray-400 hover:text-gray-600 p-2"><X size={24} /></button>
        </div>

        <input type="file" ref={cameraInputFarRef} onChange={(e) => handlePhotoAdd(e, 'FAR')} accept="image/*" capture="environment" className="hidden" />
        <input type="file" ref={galleryInputFarRef} onChange={(e) => handlePhotoAdd(e, 'FAR')} accept="image/*" className="hidden" />
        <input type="file" ref={cameraInputNearRef} onChange={(e) => handlePhotoAdd(e, 'NEAR')} accept="image/*" capture="environment" className="hidden" />
        <input type="file" ref={galleryInputNearRef} onChange={(e) => handlePhotoAdd(e, 'NEAR')} accept="image/*" className="hidden" />

        <div className="space-y-6">
           <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">원거리 사진 ({tempFarPhotos.length}/{MAX_FAR})</label>
              <div className="grid grid-cols-3 gap-2">
                {tempFarPhotos.map((p, i) => (
                  <div key={i} className="relative aspect-square rounded-lg overflow-hidden border bg-gray-50">
                    <img src={p} className="w-full h-full object-cover" decoding="async" loading="lazy" onClick={() => setViewerState({isOpen: true, photos: tempFarPhotos, index: i})} />
                    <button onClick={() => removePhoto('FAR', i)} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 shadow-sm"><X size={10} /></button>
                  </div>
                ))}
                {tempFarPhotos.length < MAX_FAR && (
                  <button onClick={() => cameraInputFarRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-brand-50 border border-brand-200 text-brand-700 hover:bg-brand-100 transition shadow-sm active:scale-95">
                      <Camera size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">사진 촬영</span>
                  </button>
                )}
                {tempFarPhotos.length < MAX_FAR && (
                  <button onClick={() => galleryInputFarRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100 transition active:scale-95">
                      <ImageIcon size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">앨범</span>
                  </button>
                )}
              </div>
           </div>

           <div>
              <label className="block text-sm font-bold text-gray-700 mb-2">근거리 사진 ({tempNearPhotos.length}/{MAX_NEAR})</label>
              <div className="grid grid-cols-3 gap-2">
                {tempNearPhotos.map((p, i) => (
                  <div key={i} className="relative aspect-square rounded-lg overflow-hidden border bg-gray-50">
                    <img src={p} className="w-full h-full object-cover" decoding="async" loading="lazy" onClick={() => setViewerState({isOpen: true, photos: tempNearPhotos, index: i})} />
                    <button onClick={() => removePhoto('NEAR', i)} className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 shadow-sm"><X size={10} /></button>
                  </div>
                ))}
                {tempNearPhotos.length < MAX_NEAR && (
                  <button onClick={() => cameraInputNearRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-brand-50 border border-brand-200 text-brand-700 hover:bg-brand-100 transition shadow-sm active:scale-95">
                      <Camera size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">사진 촬영</span>
                  </button>
                )}
                {tempNearPhotos.length < MAX_NEAR && (
                   <button onClick={() => galleryInputNearRef.current?.click()} className="aspect-square rounded-lg flex flex-col items-center justify-center bg-gray-50 border border-gray-200 text-gray-500 hover:bg-gray-100 transition active:scale-95">
                      <ImageIcon size={24} className="mb-1"/>
                      <span className="text-[10px] font-bold">앨범</span>
                  </button>
                )}
              </div>
           </div>

          <div>
            <div className="flex justify-between items-center mb-2">
              <label className="block text-sm font-bold text-gray-700">하자 내용</label>
              <span className="text-[10px] text-gray-400 font-medium">* 번호 자동 부여됨</span>
            </div>
            <textarea value={description} onChange={e => setDescription(e.target.value)} placeholder="번호 없이 내용만 입력하세요 (예: 벽지 들뜸, 타일 깨짐)" className="w-full p-4 border rounded-xl h-24 focus:ring-2 focus:ring-brand-500 outline-none resize-none text-sm" />
          </div>

          {matchingStandard && (
            <div className="p-3 bg-yellow-50 border border-yellow-200 rounded-lg text-xs">
              <p className="font-bold text-yellow-800 mb-1">⚖️ 법적 기준: {matchingStandard.title}</p>
              <div className="text-gray-600 line-clamp-3">{matchingStandard.content}</div>
            </div>
          )}
          <button onClick={handleSaveDefect} className="w-full py-4 bg-brand-600 text-white font-bold rounded-xl shadow-md">저장하기</button>
        </div>
        <AnimatePresence>
          {viewerState.isOpen && <PhotoViewer photos={viewerState.photos} initialIndex={viewerState.index} onClose={() => setViewerState(p => ({...p, isOpen: false}))} />}
        </AnimatePresence>
      </div>
    );
  }

  return (
    <div className="max-w-md mx-auto pb-32 h-full flex flex-col">
      <div className="mb-4">
        <div className="flex items-center justify-between mb-2 px-1">
          <h2 className="text-lg font-bold text-gray-800 flex items-center gap-2"><LayoutGrid size={20} className="text-brand-600" /> 구역 선택</h2>
          <div className="flex gap-1">
            <button onClick={() => { setShowTeamModal(true); setPreparedFile(null); }} className="text-[10px] font-bold px-2 py-1 bg-brand-50 text-brand-700 rounded border border-brand-200 flex items-center gap-1 transition-colors hover:bg-brand-100"><Users size={12}/> 협업</button>
            <button onClick={() => setIsReordering(true)} className={`text-[10px] font-bold px-2 py-1 rounded border flex items-center gap-1 transition-all ${isReordering ? 'bg-brand-600 text-white border-brand-600 shadow-sm' : 'bg-gray-50 text-gray-600 border-gray-200'}`}>
               <ArrowLeftRight size={12}/>
               순서
            </button>
